-- Private staged227. No217/219/221 bytes are changed.
INSERT INTO sys_perm_resource(resource_code,label)VALUES('payroll_payment','工资资金与回执'),('payroll_filing','薪税供款文件与申报回执')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,p.resource_code,true,true FROM sys_role r CROSS JOIN sys_perm_resource p WHERE r.code IN('ty_group_hr_director')AND p.resource_code IN('payroll_payment','payroll_filing')ON CONFLICT DO NOTHING;
CREATE TABLE ty_pay_standard_pack(
 code text PRIMARY KEY,system text NOT NULL,currency text NOT NULL,valid_from date NOT NULL,valid_to date,reviewed_on date NOT NULL,data jsonb NOT NULL,source_hash text NOT NULL,CHECK(valid_to IS NULL OR valid_to>valid_from)
);
CREATE TRIGGER ty_pay_standard_pack_immutable BEFORE UPDATE OR DELETE ON ty_pay_standard_pack FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE TABLE ty_pay_cash_recipient(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,person_id bigint NOT NULL,employment_id bigint NOT NULL,revision integer NOT NULL CHECK(revision>0),
 actual_employer_key text NOT NULL,actual_relationship_key text NOT NULL,relationship_config_id bigint NOT NULL REFERENCES ty_pay_config(id),currency text NOT NULL CHECK(currency IN('CNY','HKD')),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','revoked')),bank_cipher jsonb NOT NULL,bank_fingerprint text NOT NULL,masked_account text NOT NULL,
 demo_only boolean NOT NULL DEFAULT false,evidence_ref text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),UNIQUE(employment_id,currency,revision),CHECK(approved_by IS NULL OR approved_by<>created_by),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE TABLE ty_pay_fund_parent(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,person_id bigint NOT NULL,employment_id bigint NOT NULL,
 period date NOT NULL,actual_employer_key text NOT NULL,actual_relationship_key text NOT NULL,pay_subject_key text NOT NULL,currency text NOT NULL CHECK(currency IN('CNY','HKD')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),UNIQUE(group_id,person_id,actual_employer_key,actual_relationship_key,period,pay_subject_key,currency),CHECK(extract(day FROM period)=1)
);
CREATE TABLE ty_pay_payment_order(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint NOT NULL REFERENCES ty_pay_fund_parent(id),recipient_id bigint NOT NULL REFERENCES ty_pay_cash_recipient(id),amount numeric(24,2)NOT NULL CHECK(amount>0 AND amount<>'NaN'::numeric),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','exported_unknown','partially_confirmed','confirmed','rejected','cancelled')),source_hash text NOT NULL,recipient_fingerprint text NOT NULL,expected_payment_date date NOT NULL,
 demo_only boolean NOT NULL DEFAULT false,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),execution_actor_id bigint REFERENCES sys_account(id),workflow_instance_id bigint REFERENCES ty_workflow_instance(id),
 revision int NOT NULL DEFAULT 1 CHECK(revision>0),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,file_exported_at timestamptz,
 CHECK(approved_by IS NULL OR approved_by<>created_by),CHECK(status IN('draft','rejected','cancelled')OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE TABLE ty_pay_payment_receipt(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),order_id bigint NOT NULL REFERENCES ty_pay_payment_order(id),kind text NOT NULL CHECK(kind IN('settled','rejected_remaining')),
 amount numeric(24,2)NOT NULL CHECK(amount>=0 AND amount<>'NaN'::numeric),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected')),
 source_kind text NOT NULL CHECK(source_kind IN('manual_reviewed_external_evidence','demo_simulated')),issuer text NOT NULL,external_ref text NOT NULL,line_key text NOT NULL,document_hash text NOT NULL,source_locator text NOT NULL,observed_on date NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,source_hash text NOT NULL,
 CHECK(approved_by IS NULL OR approved_by<>created_by),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL),CHECK(kind='settled'AND amount>0 OR kind='rejected_remaining'AND amount=0)
);
-- One external line has one effect. Statements can legitimately have many lines.
CREATE UNIQUE INDEX ty_pay_receipt_external_line ON ty_pay_payment_receipt(group_id,issuer,external_ref,line_key)WHERE status='approved';
CREATE UNIQUE INDEX ty_pay_receipt_document_line ON ty_pay_payment_receipt(group_id,document_hash,line_key)WHERE status='approved';
CREATE TABLE ty_pay_filing(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,system text NOT NULL,kind text NOT NULL CHECK(kind IN('CN_IIT','CN_SOCIAL','CN_HOUSING','HK_MPF','HK_IR56')),
 period date NOT NULL,version int NOT NULL CHECK(version>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','reviewed','exported_unknown','reported_submitted','reported_accepted','reported_rejected','superseded','workflow_rejected','workflow_cancelled')),
 template_code text NOT NULL,template_version text NOT NULL,source_hash text NOT NULL,snapshot jsonb NOT NULL,demo_only boolean NOT NULL DEFAULT false,formal_ready boolean NOT NULL DEFAULT false,
 created_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),reviewed_at timestamptz,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),UNIQUE(group_id,company_id,system,kind,period,version),CHECK(reviewed_by IS NULL OR reviewed_by<>created_by)
);
CREATE TABLE ty_pay_filing_event(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,filing_id bigint NOT NULL REFERENCES ty_pay_filing(id),kind text NOT NULL CHECK(kind IN('submitted','accepted','rejected','remittance_reported')),
 evidence_ref text NOT NULL,document_hash text NOT NULL,external_ref text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected')),
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 CHECK(approved_by IS NULL OR approved_by<>created_by),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE UNIQUE INDEX ty_pay_filing_evidence_once ON ty_pay_filing_event(document_hash,external_ref,kind)WHERE status='approved';
CREATE FUNCTION fn_ty_pay_fund_source(g bigint,pe bigint,employer text,relationship_key text,payer text,period_key date,ccy text)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE target numeric;net_wage numeric;reimburse numeric;refs jsonb;
BEGIN
 SELECT coalesce(sum((r.totals->>'employee_cash_settlement')::numeric),0),coalesce(sum((r.totals->>'net_wage_payable')::numeric),0),coalesce(sum((r.totals->>'reimbursement')::numeric),0),coalesce(jsonb_agg(jsonb_build_object('row_id',r.id,'batch_id',b.id,'company_id',r.company_id,'employment_id',r.employment_id,'person_id',r.person_id,'relationship_config_id',rc.id,'amount',r.totals->>'employee_cash_settlement','net_wage',r.totals->>'net_wage_payable','reimbursement',r.totals->>'reimbursement','totals_hash',md5(r.totals::text))ORDER BY r.id),'[]'::jsonb)INTO target,net_wage,reimburse,refs FROM public.ty_pay_row r JOIN public.ty_pay_batch b ON b.id=r.batch_id JOIN public.ty_pay_config rc ON rc.id=r.relationship_config_id
 WHERE r.group_id=g AND r.person_id=pe AND rc.data->>'actual_employer_key'=employer AND rc.data->>'actual_relationship_key'=relationship_key AND b.period=period_key AND b.pay_subject_key=payer AND b.currency=ccy AND b.status='confirmed';
 RETURN jsonb_build_object('target',round(target,2)::text,'net_wage',round(net_wage,2)::text,'reimbursement',round(reimburse,2)::text,'source_refs',refs,'source_hash',md5(jsonb_build_object('group',g,'person',pe,'employer',employer,'relationship',relationship_key,'payer',payer,'period',period_key,'currency',ccy,'rows',refs)::text));
END;$$;
CREATE FUNCTION fn_ty_pay_fund_state(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE p public.ty_pay_fund_parent%ROWTYPE;src jsonb;target numeric;paid numeric;held numeric;
BEGIN
 SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=parent_key;IF p.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金父义务不存在';END IF;
 src:=public.fn_ty_pay_fund_source(p.group_id,p.person_id,p.actual_employer_key,p.actual_relationship_key,p.pay_subject_key,p.period,p.currency);target:=(src->>'target')::numeric;
 SELECT coalesce(sum(r.amount),0)INTO paid FROM public.ty_pay_payment_receipt r JOIN public.ty_pay_payment_order o ON o.id=r.order_id WHERE o.parent_id=p.id AND r.status='approved'AND r.kind='settled';
 SELECT coalesce(sum(greatest(0,o.amount-coalesce((SELECT sum(r.amount)FROM public.ty_pay_payment_receipt r WHERE r.order_id=o.id AND r.status='approved'AND r.kind='settled'),0))),0)INTO held FROM public.ty_pay_payment_order o WHERE o.parent_id=p.id AND o.status IN('approved','exported_unknown','partially_confirmed');
 RETURN src||jsonb_build_object('settled',round(paid,2)::text,'held',round(held,2)::text,'available',round(greatest(0,target-paid-held),2)::text,'overpaid_review',round(greatest(0,paid-target),2)::text,'unresolved_overcommitment',round(greatest(0,paid+held-target),2)::text,'bank_verified',false);
END;$$;
CREATE TRIGGER ty_pay_fund_parent_immutable BEFORE UPDATE OR DELETE ON ty_pay_fund_parent FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE FUNCTION fn_ty_pay_review_person(actor bigint,g bigint)RETURNS bigint LANGUAGE sql STABLE SET search_path=''AS $$SELECT coalesce((SELECT person_id FROM public.ty_operator_binding WHERE account_id=actor AND group_id=g AND status='active'),(SELECT person_id FROM public.ty_test_account_profile WHERE account_id=actor AND group_id=g),(SELECT id FROM public.ty_person WHERE group_id=g AND legacy_person_id=(SELECT person_id FROM public.sys_account WHERE id=actor)))$$;
CREATE FUNCTION fn_ty_pay_distinct_reviewer(creator bigint,reviewer bigint,g bigint,beneficiary bigint DEFAULT NULL)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$SELECT reviewer IS NOT NULL AND creator<>reviewer AND NOT coalesce(public.fn_ty_pay_review_person(creator,g)=public.fn_ty_pay_review_person(reviewer,g),false)AND NOT coalesce(public.fn_ty_pay_review_person(reviewer,g)=beneficiary,false)$$;
CREATE FUNCTION fn_ty_pay_fund_identity_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.ty_pay_row r JOIN public.ty_pay_batch b ON b.id=r.batch_id JOIN public.ty_pay_config rc ON rc.id=r.relationship_config_id WHERE r.group_id=NEW.group_id AND r.company_id=NEW.company_id AND r.person_id=NEW.person_id AND r.employment_id=NEW.employment_id AND b.period=NEW.period AND b.currency=NEW.currency AND b.pay_subject_key=NEW.pay_subject_key AND b.status='confirmed'AND rc.data->>'actual_employer_key'=NEW.actual_employer_key AND rc.data->>'actual_relationship_key'=NEW.actual_relationship_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资资金根须从同人同实际关系及付款主体的已确认来源建立';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_fund_identity_guard BEFORE INSERT ON ty_pay_fund_parent FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_fund_identity_guard();
CREATE FUNCTION fn_ty_pay_cash_identity_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_pay_fund_parent%ROWTYPE;e public.ty_employment%ROWTYPE;r public.ty_pay_cash_recipient%ROWTYPE;c public.ty_pay_config%ROWTYPE;s jsonb;paid numeric;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资资金及凭据历史不可删除';END IF;
 IF TG_TABLE_NAME='ty_pay_cash_recipient'THEN
  SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;IF e.group_id<>NEW.group_id OR e.company_id<>NEW.company_id OR e.person_id<>NEW.person_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='收款资料须属于真实工资受益人';END IF;
  SELECT*INTO c FROM public.ty_pay_config WHERE id=NEW.relationship_config_id;IF c.kind<>'relationship'OR c.status<>'approved'OR c.group_id<>NEW.group_id OR c.company_id<>NEW.company_id OR c.employment_id<>NEW.employment_id OR c.person_id<>NEW.person_id OR c.data->>'actual_employer_key'IS DISTINCT FROM NEW.actual_employer_key OR c.data->>'actual_relationship_key'IS DISTINCT FROM NEW.actual_relationship_key THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='收款版本须绑定确切已核实际法律关系';END IF;
  IF NEW.status='approved'AND(TG_OP='INSERT'OR OLD.status='draft')AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,NEW.group_id,NEW.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='收款本人或同自然人别名不可自核';END IF;
  IF TG_OP='UPDATE'AND OLD.status<>'draft'AND ROW(NEW.approved_by,NEW.approved_at)IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原收款核准历史不可改写';END IF;
  IF TG_OP='UPDATE'AND(to_jsonb(NEW)-'status'-'approved_by'-'approved_at'IS DISTINCT FROM to_jsonb(OLD)-'status'-'approved_by'-'approved_at'OR OLD.status<>'draft'AND NEW.status<>'revoked')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='收款资料须新版本修订，已核原件不改写';END IF;
 ELSIF TG_TABLE_NAME='ty_pay_payment_order'THEN
  SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=NEW.parent_id FOR UPDATE;SELECT*INTO r FROM public.ty_pay_cash_recipient WHERE id=NEW.recipient_id;
  IF r.group_id<>p.group_id OR r.person_id<>p.person_id OR r.actual_employer_key<>p.actual_employer_key OR r.actual_relationship_key<>p.actual_relationship_key OR r.currency<>p.currency OR r.demo_only<>NEW.demo_only OR NEW.recipient_fingerprint<>r.bank_fingerprint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款须引用同人同关系同币种已核收款版本';END IF;
  IF NEW.status='approved'AND(TG_OP='INSERT'OR OLD.status='draft')AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,p.group_id,p.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资付款不得由本人或同一自然人别名核准';END IF;
  IF r.status<>'approved'AND(TG_OP='INSERT'OR OLD.status='draft'OR OLD.status='approved'AND NEW.status='exported_unknown')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='新付款或文件须用有效已核收款版本，旧外部到账仍保留真实凭据';END IF;
  IF TG_OP='UPDATE'AND OLD.status<>'draft'AND ROW(NEW.approved_by,NEW.approved_at)IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原资金核准人员和时间不可改写';END IF;
  IF TG_OP='UPDATE'AND to_jsonb(NEW)-'status'-'approved_by'-'approved_at'-'revision'-'execution_actor_id'-'workflow_instance_id'-'file_exported_at'IS DISTINCT FROM to_jsonb(OLD)-'status'-'approved_by'-'approved_at'-'revision'-'execution_actor_id'-'workflow_instance_id'-'file_exported_at'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款金额和来源不可覆盖，须取消或核对后另建';END IF;
  IF TG_OP='INSERT'OR OLD.status='draft'AND NEW.status='approved'THEN
   s:=public.fn_ty_pay_fund_state(p.id);IF NEW.source_hash IS DISTINCT FROM s->>'source_hash'THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='确认工资来源已变，须重新核对付款';END IF;
   IF NEW.amount>(s->>'available')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款超过工资资金余额，已付及全部未决占用不可重复';END IF;
  END IF;
  IF TG_OP='UPDATE'AND OLD.status IN('exported_unknown','partially_confirmed')AND NEW.status IN('rejected','cancelled')AND NOT EXISTS(SELECT 1 FROM public.ty_pay_payment_receipt rr WHERE rr.order_id=NEW.id AND rr.status='approved'AND rr.kind='rejected_remaining')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已导出可能外发或未知结果不能无凭据释放再付';END IF;
  IF TG_OP='UPDATE'AND NEW.status<>OLD.status AND NOT(OLD.status='draft'AND NEW.status IN('approved','cancelled','rejected')OR OLD.status='approved'AND NEW.status IN('exported_unknown','cancelled','rejected')OR OLD.status IN('exported_unknown','partially_confirmed')AND NEW.status IN('partially_confirmed','confirmed','rejected'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资资金状态不可回退或绕过批准和外部回执';END IF;
  IF TG_OP='UPDATE'AND OLD.status='approved'AND NEW.status='exported_unknown'THEN s:=public.fn_ty_pay_fund_state(p.id);IF NEW.source_hash IS DISTINCT FROM s->>'source_hash'OR(s->>'unresolved_overcommitment')::numeric>0 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='导出前工资来源或资金余额已变，须核对原指令';END IF;END IF;
  IF NEW.status='confirmed'THEN SELECT coalesce(sum(rr.amount),0)INTO paid FROM public.ty_pay_payment_receipt rr WHERE rr.order_id=NEW.id AND rr.status='approved'AND rr.kind='settled';IF paid<>NEW.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未有足额已核回执不能显示工资已结';END IF;END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_recipient_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_cash_recipient FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_cash_identity_guard();
CREATE TRIGGER ty_pay_order_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_payment_order FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_cash_identity_guard();
CREATE FUNCTION fn_ty_pay_receipt_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE o public.ty_pay_payment_order%ROWTYPE;p public.ty_pay_fund_parent%ROWTYPE;paid numeric;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款外部凭据不可删除';END IF;
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-'status'-'approved_by'-'approved_at'IS DISTINCT FROM to_jsonb(OLD)-'status'-'approved_by'-'approved_at'OR OLD.status<>'draft')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核凭据不可覆盖';END IF;
 SELECT*INTO o FROM public.ty_pay_payment_order WHERE id=NEW.order_id FOR UPDATE;SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=o.parent_id FOR UPDATE;
 IF o.id IS NULL OR NEW.group_id<>(SELECT group_id FROM public.ty_pay_fund_parent WHERE id=o.parent_id)OR(TG_OP='INSERT'OR NEW.status='approved')AND o.status NOT IN('exported_unknown','partially_confirmed')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='须先记录付款文件可能外发/提交待核，不能凭空核成已付';END IF;
 IF o.demo_only IS DISTINCT FROM(NEW.source_kind='demo_simulated')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='模拟回执与真实外部凭据不能混账';END IF;
 IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,p.group_id,p.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资到账回执须独立非受益自然人复核';END IF;
 IF NEW.status='approved'THEN SELECT coalesce(sum(amount),0)INTO paid FROM public.ty_pay_payment_receipt WHERE order_id=o.id AND status='approved'AND kind='settled'AND id<>NEW.id;IF paid+NEW.amount>o.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款回执重复或超过已批准金额';END IF;END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_receipt_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_payment_receipt FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_receipt_guard();

CREATE FUNCTION fn_ty_pay_filing_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报和供款底稿历史不可删除';END IF;
 IF NEW.formal_ready THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='尚未装配已核政府/机构模板与实名登记，不能把工作底稿标成正式上传文件';END IF;
 IF TG_OP='UPDATE'AND to_jsonb(NEW)-'status'-'reviewed_by'-'reviewed_at'IS DISTINCT FROM to_jsonb(OLD)-'status'-'reviewed_by'-'reviewed_at'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报底稿须新版本更正，不能覆盖原来源';END IF;
 IF NEW.status='reviewed'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.reviewed_by,NEW.group_id,NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪税底稿须独立自然人复核';END IF;
 IF TG_OP='UPDATE'AND OLD.status<>'draft'AND ROW(NEW.reviewed_by,NEW.reviewed_at)IS DISTINCT FROM ROW(OLD.reviewed_by,OLD.reviewed_at)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原底稿复核历史不可改变';END IF;
 IF TG_OP='UPDATE'AND NEW.status<>OLD.status AND NOT(OLD.status='draft'AND NEW.status IN('reviewed','workflow_rejected','workflow_cancelled')OR OLD.status='reviewed'AND NEW.status IN('exported_unknown','superseded')OR OLD.status IN('exported_unknown','reported_submitted','reported_rejected')AND NEW.status IN('reported_submitted','reported_accepted','reported_rejected','superseded')OR OLD.status='reported_accepted'AND NEW.status='superseded')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报状态须按实际已核事件前进';END IF;
 IF NEW.status IN('reported_submitted','reported_accepted','reported_rejected')AND NOT EXISTS(SELECT 1 FROM public.ty_pay_filing_event e WHERE e.filing_id=NEW.id AND e.status='approved'AND e.kind=CASE NEW.status WHEN'reported_submitted'THEN'submitted'WHEN'reported_accepted'THEN'accepted'ELSE'rejected'END)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='机构状态须有独立核定的实际回执';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_filing_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_filing FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_filing_guard();
CREATE FUNCTION fn_ty_pay_filing_event_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE f public.ty_pay_filing%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报回执不可删除';END IF;
 SELECT*INTO f FROM public.ty_pay_filing WHERE id=NEW.filing_id FOR UPDATE;
 IF f.status NOT IN('exported_unknown','reported_submitted','reported_accepted','reported_rejected')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='先生成有据底稿后才能登记外部状态';END IF;
 IF TG_OP='UPDATE'AND(OLD.status<>'draft'OR to_jsonb(NEW)-'status'-'approved_by'-'approved_at'IS DISTINCT FROM to_jsonb(OLD)-'status'-'approved_by'-'approved_at')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报回执原件不得覆盖';END IF;
 IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,f.group_id,NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报回执须另一自然人核定';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_filing_event_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_filing_event FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_filing_event_guard();
CREATE FUNCTION fn_ty_pay_filing_source(g bigint,co bigint,sys text,k text,pe date)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE rows jsonb;unknown_count int;body jsonb;
BEGIN
 IF(k IN('CN_IIT','CN_SOCIAL','CN_HOUSING'))IS DISTINCT FROM(sys='CN_PAYROLL')OR k NOT IN('CN_IIT','CN_SOCIAL','CN_HOUSING','HK_MPF','HK_IR56')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报种类与算薪体系不一致';END IF;
 IF k='HK_IR56'THEN
  SELECT count(*)INTO unknown_count FROM public.ty_pay_item i JOIN public.ty_pay_row r ON r.id=i.row_id JOIN public.ty_pay_batch b ON b.id=r.batch_id JOIN public.ty_pay_config rule ON rule.id=b.rulebook_id
  WHERE r.group_id=g AND r.company_id=co AND b.system=sys AND b.status='confirmed'AND b.period=pe AND i.category IN('cash_earnings','noncash_shadow')AND coalesce(rule.data->'filing_treatments'->'HK_IR56'->>i.code,'pending')NOT IN('include','exclude');
  IF unknown_count>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='IR56雇主报税逐项待遇未核定，不能把现金工资合计直接当报税收入';END IF;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('adoption_id',a.id,'item_id',i.id,'batch_id',b.id,'company_id',r.company_id,'person_id',r.person_id,'employment_id',r.employment_id,'code',i.code,'category',i.category,'amount',a.delta::text,'relationship_config_id',rc.id,'actual_employer_key',rc.data->>'actual_employer_key','actual_relationship_key',rc.data->>'actual_relationship_key','wage_period',b.period,'stat_period',a.source_snapshot->>'stat_period','tax_subject_key',b.tax_subject_key,'contribution_subject_key',b.contribution_subject_key,'assessment',CASE WHEN a.source_domain='statutory_calculation'THEN a.source_snapshot ELSE NULL END)ORDER BY a.id),'[]'::jsonb)INTO rows
 FROM public.ty_pay_adoption a JOIN public.ty_pay_item i ON i.adoption_id=a.id JOIN public.ty_pay_row r ON r.id=i.row_id JOIN public.ty_pay_batch b ON b.id=r.batch_id JOIN public.ty_pay_config rc ON rc.id=r.relationship_config_id JOIN public.ty_pay_config rule ON rule.id=b.rulebook_id
 WHERE r.group_id=g AND r.company_id=co AND b.system=sys AND b.status='confirmed'AND a.state='confirmed'AND CASE WHEN k='HK_IR56'THEN b.period=pe AND i.category IN('cash_earnings','noncash_shadow')AND rule.data->'filing_treatments'->'HK_IR56'->>i.code='include'ELSE a.source_domain='statutory_calculation'AND(a.source_snapshot->>'stat_period')::date=pe AND CASE k WHEN'CN_IIT'THEN i.code='CN_IIT_WITHHOLD'WHEN'CN_SOCIAL'THEN i.code~'^CN_(EMP|ER)_'AND i.code NOT IN('CN_EMP_HOUSING_FUND','CN_ER_HOUSING_FUND')WHEN'CN_HOUSING'THEN i.code IN('CN_EMP_HOUSING_FUND','CN_ER_HOUSING_FUND')WHEN'HK_MPF'THEN i.code IN('HK_EMP_MPF_MANDATORY','HK_ER_MPF_MANDATORY')ELSE false END END;
 IF jsonb_array_length(rows)=0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='此范围及归属期没有已确认的对应法定工资行，未知不能形成0申报';END IF;
 body:=jsonb_build_object('group_id',g,'company_id',co,'system',sys,'kind',k,'period',pe,'rows',rows,'workings_not_formal',true,'payment_verified',false);
 RETURN jsonb_build_object('snapshot',body,'source_hash',md5(body::text));
END;$$;
CREATE FUNCTION fn_ty_pay_filing_authority_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE s jsonb;BEGIN
 IF TG_OP='INSERT'OR NEW.status IN('reviewed','exported_unknown')AND NEW.status IS DISTINCT FROM OLD.status THEN s:=public.fn_ty_pay_filing_source(NEW.group_id,NEW.company_id,NEW.system,NEW.kind,NEW.period);IF NEW.source_hash IS DISTINCT FROM s->>'source_hash'OR NEW.snapshot IS DISTINCT FROM s->'snapshot'THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='申报底稿来源已变或不来自真实已确认工资，须重新生成';END IF;END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_filing_authority_guard BEFORE INSERT OR UPDATE ON ty_pay_filing FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_filing_authority_guard();

-- Serialize a new wage tranche with all existing shared funding reservations.
-- A later lawful wage correction may expose an overpayment; it does not erase
-- an already observed external payment. Export always rechecks the frozen hash.
CREATE FUNCTION fn_ty_pay_cash_source_lock()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF NEW.status='confirmed'AND OLD.status<>'confirmed'THEN
  PERFORM id FROM public.ty_group WHERE id=NEW.group_id FOR UPDATE;
  PERFORM p.id FROM public.ty_pay_fund_parent p WHERE p.group_id=NEW.group_id AND p.period=NEW.period AND p.currency=NEW.currency AND p.pay_subject_key=NEW.pay_subject_key AND EXISTS(SELECT 1 FROM public.ty_pay_row r JOIN public.ty_pay_config rc ON rc.id=r.relationship_config_id WHERE r.batch_id=NEW.id AND r.person_id=p.person_id AND rc.data->>'actual_employer_key'=p.actual_employer_key AND rc.data->>'actual_relationship_key'=p.actual_relationship_key)ORDER BY p.id FOR UPDATE;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER a_ty_pay_cash_source_lock BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_cash_source_lock();
CREATE TABLE ty_pay_industry_basis(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,person_id bigint NOT NULL,employment_id bigint NOT NULL,
 actual_employer_key text NOT NULL,subject_key text NOT NULL,period date NOT NULL,revision int NOT NULL CHECK(revision>0),
 source_kind text NOT NULL CHECK(source_kind IN('native_time_and_reviewed_allocation','external_reviewed_workdays_and_allocation')),report_root_id bigint REFERENCES ty_time_report_root(id),report_id bigint REFERENCES ty_time_report_version(id),report_head_revision int,report_source_hash text,
 mode text NOT NULL CHECK(mode IN('daily_rated','non_daily_rated')),groups jsonb NOT NULL,eligibility jsonb NOT NULL,document_hash text NOT NULL,evidence_ref text NOT NULL,source_locator text NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','revoked')),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),UNIQUE(group_id,person_id,actual_employer_key,subject_key,period,revision),
 CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL),CHECK(extract(day FROM period)=1)
);
CREATE FUNCTION fn_ty_pay_industry_basis_valid(p_id bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE b public.ty_pay_industry_basis%ROWTYPE;g jsonb;f jsonb;groups_seen daterange[]:='{}';dates date[]:='{}';facts text[]:='{}';r public.ty_time_report_root%ROWTYPE;v public.ty_time_report_version%ROWTYPE;wd date;total numeric:=0;check_dates date[];
BEGIN
 SELECT*INTO b FROM public.ty_pay_industry_basis WHERE id=p_id;
 IF b.id IS NULL OR b.status<>'approved'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业工资期工作日与分配须独立核准';END IF;
 IF EXISTS(SELECT 1 FROM public.ty_pay_industry_basis n WHERE n.group_id=b.group_id AND n.person_id=b.person_id AND n.actual_employer_key=b.actual_employer_key AND n.subject_key=b.subject_key AND n.period=b.period AND n.status='approved'AND n.revision>b.revision)THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='行业工作日依据已有新核准版本';END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['verified','industry','casual','industryScheme','contributionHoliday'])k WHERE jsonb_typeof(b.eligibility->k)IS DISTINCT FROM'boolean')OR b.eligibility->>'verified'IS DISTINCT FROM'true'OR b.eligibility->>'industry'IS DISTINCT FROM'true'OR b.eligibility->>'casual'IS DISTINCT FROM'true'OR b.eligibility->>'industryScheme'IS DISTINCT FROM'true'OR b.eligibility->>'contributionHoliday'IS DISTINCT FROM'false'OR jsonb_typeof(b.groups)<>'array'OR jsonb_array_length(b.groups)=0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='须逐项核准行业临时资格及原工资期，不可从PT推定或套供款假期';END IF;
 FOR g IN SELECT value FROM jsonb_array_elements(b.groups)LOOP
  IF(g->>'from')::date>= (g->>'to')::date OR(g->>'from')::date<b.period OR(g->>'to')::date>b.period+interval'1 month'OR EXISTS(SELECT 1 FROM unnest(groups_seen)x WHERE x&&daterange((g->>'from')::date,(g->>'to')::date,'[)'))OR jsonb_typeof(g->'facts')IS DISTINCT FROM'array'OR jsonb_array_length(g->'facts')=0 OR g->>'key'IS NULL OR g->>'from'IS NULL OR g->>'to'IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原工资期须有序、不重叠且在本供款月，跨月工资期须先单独核定不能截断';END IF;
  groups_seen:=array_append(groups_seen,daterange((g->>'from')::date,(g->>'to')::date,'[)'));check_dates:='{}';
  FOR f IN SELECT value FROM jsonb_array_elements(g->'facts')LOOP
   wd:=(f->>'date')::date;IF wd IS NULL OR wd<(g->>'from')::date OR wd>=(g->>'to')::date OR coalesce(f->>'key','')='' OR f->>'key'=ANY(facts)OR wd=ANY(dates)AND NOT(wd=ANY(check_dates))OR jsonb_typeof(f->'employeeEligible')IS DISTINCT FROM'boolean'OR jsonb_typeof(f->'employerEligible')IS DISTINCT FROM'boolean'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工作事实键、日期及逐日两侧资格须唯一明确';END IF;
   facts:=array_append(facts,f->>'key');check_dates:=array_append(check_dates,wd);IF NOT(wd=ANY(dates))THEN dates:=array_append(dates,wd);END IF;total:=total+public.fn_ty_pay_stat_decimal(f->>'income');
  END LOOP;
 END LOOP;
 IF b.source_kind='native_time_and_reviewed_allocation'THEN
  SELECT*INTO r FROM public.ty_time_report_root WHERE id=b.report_root_id;SELECT*INTO v FROM public.ty_time_report_version WHERE id=b.report_id;
  IF r.id IS NULL OR v.id IS NULL OR r.group_id<>b.group_id OR r.employment_id<>b.employment_id OR r.person_id<>b.person_id OR r.owner_company_id<>b.company_id OR r.perspective<>'employer'OR r.period<>b.period OR r.current_report_id IS DISTINCT FROM b.report_id OR r.head_revision IS DISTINCT FROM b.report_head_revision OR v.source_hash IS DISTINCT FROM b.report_source_hash OR v.status<>'confirmed'OR v.grain<>'daily'THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='行业工作日须来自当前已确认的雇主日报头';END IF;
  IF EXISTS(SELECT 1 FROM public.ty_time_report_line l WHERE l.report_id=v.id AND l.employment_id=b.employment_id AND NOT l.receiving_store_only AND(l.work_date IS NULL OR l.worked_minutes IS NULL OR l.missing_punches IS NULL OR l.missing_punches>0))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工作日原生证据含未知/缺卡，须先核勤或转有据外部工作日核定，不能补0';END IF;
  IF EXISTS(SELECT 1 FROM public.ty_time_report_line l WHERE l.report_id=v.id AND l.employment_id=b.employment_id AND NOT l.receiving_store_only AND l.worked_minutes>0 AND NOT(l.work_date=ANY(dates)))OR EXISTS(SELECT 1 FROM unnest(dates)d WHERE NOT EXISTS(SELECT 1 FROM public.ty_time_report_line l WHERE l.report_id=v.id AND l.employment_id=b.employment_id AND NOT l.receiving_store_only AND l.work_date=d AND l.worked_minutes>0))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生实际工作日与原工资期分配不一致，不能以计划代打卡';END IF;
 ELSE IF b.report_id IS NOT NULL OR b.report_root_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='外部核定不能冒充原生考勤已验证';END IF;END IF;
 RETURN jsonb_build_object('record',to_jsonb(b),'total_income',total::text);
END;$$;
CREATE FUNCTION fn_ty_pay_industry_basis_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE e public.ty_employment%ROWTYPE;prior public.ty_pay_industry_basis%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业供款依据历史不可删除';END IF;
 SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF e.group_id<>NEW.group_id OR e.person_id<>NEW.person_id OR e.company_id<>NEW.company_id OR NOT EXISTS(SELECT 1 FROM public.ty_pay_config c WHERE c.kind='relationship'AND c.status='approved'AND c.group_id=NEW.group_id AND c.person_id=NEW.person_id AND c.employment_id=NEW.employment_id AND c.system='HK_PAYROLL'AND c.data->>'actual_employer_key'=NEW.actual_employer_key AND c.data->>'contribution_subject_key'=NEW.subject_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业供款依据须绑定确切已核法律雇主及供款主体';END IF;
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-'status'-'approved_by'-'approved_at'IS DISTINCT FROM to_jsonb(OLD)-'status'-'approved_by'-'approved_at'OR OLD.status<>'draft'AND NEW.status<>'revoked')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业依据须新版本修订，不能覆盖已核工资期';END IF;
 IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,NEW.group_id,NEW.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业供款依据须独立非受益自然人复核';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_industry_basis_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_industry_basis FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_industry_basis_guard();
-- Keep existing guard semantics byte-for-byte except this explicitly typed new
-- branch. A drifted upstream function fails migration instead of being dropped.
DO $$DECLARE src text;BEGIN
 src:=pg_get_functiondef('public.fn_ty_pay_stat_policy_guard()'::regprocedure);
 IF position($needle$IN('CN_IIT','CN_SOCIAL','HK_MPF_REGULAR')$needle$IN src)=0 OR position(E'  ELSE\n   IF public.fn_ty_pay_stat_decimal'IN src)=0 THEN RAISE EXCEPTION '219 policy extension drift';END IF;
 src:=replace(src,$needle$IN('CN_IIT','CN_SOCIAL','HK_MPF_REGULAR')$needle$,$replace$IN('CN_IIT','CN_SOCIAL','HK_MPF_REGULAR','HK_MPF_INDUSTRY')$replace$);src:=replace(src,E'  ELSE\n   IF public.fn_ty_pay_stat_decimal',E'  ELSIF d->>''type''<>''HK_MPF_INDUSTRY''THEN\n   IF public.fn_ty_pay_stat_decimal');EXECUTE src;
END;$$;
DO $$DECLARE src text;BEGIN
 src:=pg_get_functiondef('public.fn_ty_pay_income_scope(jsonb)'::regprocedure);
 IF position($n$IN('CN_IIT','CN_SOCIAL','HK_MPF_REGULAR')$n$IN src)=0 THEN RAISE EXCEPTION '221 income scope extension drift';END IF;
 src:=replace(src,$n$IN('CN_IIT','CN_SOCIAL','HK_MPF_REGULAR')$n$,$n$IN('CN_IIT','CN_SOCIAL','HK_MPF_REGULAR','HK_MPF_INDUSTRY')$n$);
 src:=replace(src,$n$d->>'type'='HK_MPF_REGULAR'$n$,$n$d->>'type'IN('HK_MPF_REGULAR','HK_MPF_INDUSTRY')$n$);EXECUTE src;
END;$$;
ALTER FUNCTION fn_ty_pay_stat_context(bigint,bigint,bigint,jsonb)RENAME TO fn_ty_pay_stat_context_pre227;
CREATE FUNCTION fn_ty_pay_stat_context(p_batch bigint,p_employment bigint,p_enrollment bigint,p_lines jsonb)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$
DECLARE c jsonb;p jsonb;b jsonb;r public.ty_pay_industry_basis%ROWTYPE;
BEGIN
 c:=public.fn_ty_pay_stat_context_pre227(p_batch,p_employment,p_enrollment,p_lines);
 IF c->>'type'<>'HK_MPF_INDUSTRY'THEN RETURN c;END IF;
 b:=public.fn_ty_pay_industry_basis_valid((c->'period_parameters'->>'industry_basis_id')::bigint);SELECT*INTO r FROM public.ty_pay_industry_basis WHERE id=(b->'record'->>'id')::bigint;
 IF r.group_id<>(c->>'group_id')::bigint OR r.person_id<>(c->>'person_id')::bigint OR r.actual_employer_key IS DISTINCT FROM c->>'legal_employer_key'OR r.subject_key IS DISTINCT FROM c->>'subject_key'OR r.period<>(c->>'period')::date OR(b->>'total_income')::numeric<>(c->>'native_income')::numeric+(c->'opening'->'data'->>'income')::numeric THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='原工资期分配总额须严格等于此实际雇主及供款期的真实原生工资/已核期初；变更须重核，不能凭客户端金额';END IF;
 RETURN c||jsonb_build_object('industry_basis',b->'record');
END;$$;
ALTER FUNCTION fn_ty_pay_stat_math(jsonb,text)RENAME TO fn_ty_pay_stat_math_pre227;
CREATE FUNCTION fn_ty_pay_stat_math(c jsonb,component text)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p jsonb:=c->'policy'->'data';b jsonb:=c->'industry_basis';o jsonb:=c->'opening'->'data';pp jsonb:=c->'period_parameters';g jsonb;d record;br jsonb;side text;average_income numeric;daily_income numeric;total numeric:=NULL;v numeric;has_eligible boolean;initial numeric;
BEGIN
 IF c->>'type'<>'HK_MPF_INDUSTRY'THEN RETURN public.fn_ty_pay_stat_math_pre227(c,component);END IF;
 IF component=p->>'employee_code'THEN side:='employee';ELSIF component=p->>'employer_code'THEN side:='employer';ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业供款组件不能改作工资';END IF;
 IF jsonb_typeof(pp->(side||'_eligible'))IS DISTINCT FROM'boolean'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业逐期资格未知';END IF;
 FOR g IN SELECT value FROM jsonb_array_elements(b->'groups')LOOP
  SELECT sum((value->>'income')::numeric)/count(DISTINCT value->>'date')INTO average_income FROM jsonb_array_elements(g->'facts');
  FOR d IN SELECT value->>'date'AS work_date,sum((value->>'income')::numeric)income,bool_and((value->>(side||'Eligible'))::boolean)eligible,count(DISTINCT value->>(side||'Eligible'))eligibility_variants FROM jsonb_array_elements(g->'facts')GROUP BY value->>'date'LOOP
   IF d.eligibility_variants<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同日不同班次供款资格矛盾';END IF;
   IF NOT((pp->>(side||'_eligible'))::boolean AND d.eligible)THEN CONTINUE;END IF;
   daily_income:=CASE WHEN b->>'mode'='daily_rated'THEN d.income ELSE average_income END;v:=NULL;
   FOR br IN SELECT value FROM jsonb_array_elements(p->'bands')LOOP IF daily_income>=(br->>'lower')::numeric AND(br->>'upper'IS NULL OR daily_income<(br->>'upper')::numeric)THEN v:=(br->>side)::numeric;EXIT;END IF;END LOOP;
   IF v IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业供款日额表不完整';END IF;total:=coalesce(total,0)+v;
  END LOOP;
 END LOOP;
 initial:=(o->>(side||'_target'))::numeric;IF total IS NULL THEN RETURN jsonb_build_object('state','not_applicable','target',NULL,'initial',initial::text);END IF;
 total:=total+(pp->>(side||'_arrears'))::numeric;RETURN jsonb_build_object('state',CASE WHEN total=0 THEN'confirmed_zero'ELSE'calculated'END,'target',round(total,2)::text,'initial',round(initial,2)::text);
END;$$;
CREATE FUNCTION fn_ty_pay_industry_policy_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_pay_standard_pack%ROWTYPE;d jsonb:=NEW.data;k text;v jsonb;
BEGIN
 IF NEW.kind='policy'AND d->>'type'='HK_MPF_INDUSTRY'THEN
  SELECT*INTO p FROM public.ty_pay_standard_pack WHERE code=d->>'standard_pack_id';
  IF p.code IS NULL OR p.code<>'HK_MPF_INDUSTRY_20260430'OR NEW.system<>'HK_PAYROLL'OR NEW.valid_from<p.valid_from OR p.valid_to IS NOT NULL AND(NEW.valid_to IS NULL OR NEW.valid_to>p.valid_to)OR d->>'scheme_type'IS DISTINCT FROM'industry'OR d->>'employee_code'IS DISTINCT FROM'HK_EMP_MPF_MANDATORY'OR d->>'employer_code'IS DISTINCT FROM'HK_ER_MPF_MANDATORY'OR d->'bands'IS DISTINCT FROM p.data->'parameters'->'bands'OR d->>'contribution_holiday'IS DISTINCT FROM'false'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='行业临时MPF必须使用已装适用官方日额表与独立资格，不改金额、不套供款假期';END IF;
  PERFORM public.fn_ty_pay_income_scope(d);
  FOR k,v IN SELECT*FROM jsonb_each(d->'scope_by_item')LOOP IF v='"include"'::jsonb AND EXISTS(SELECT 1 FROM public.ty_pay_item_catalog c WHERE c.code=k AND c.category='noncash_shadow')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='MPF相关入息不能直接加入非现金影子待遇';END IF;END LOOP;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_industry_policy_guard BEFORE INSERT OR UPDATE ON ty_pay_stat_config FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_industry_policy_guard();
