--226 is an explicit predecessor: shared employee funds have true foreign keys.
ALTER TABLE ty_wf_personal_instruction ADD CONSTRAINT ty_wf_personal_fund_fk FOREIGN KEY(fund_parent_id)REFERENCES ty_pay_fund_parent(id);
CREATE TABLE ty_pay_agency_reservation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint NOT NULL REFERENCES ty_pay_fund_parent(id),instruction_id bigint NOT NULL UNIQUE REFERENCES ty_wf_personal_instruction(id),amount numeric(24,2)NOT NULL CHECK(amount>0 AND amount<>'NaN'::numeric),source_hash text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE ty_pay_agency_effect(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reservation_id bigint NOT NULL REFERENCES ty_pay_agency_reservation(id),receipt_id bigint NOT NULL UNIQUE REFERENCES ty_wf_personal_receipt(id),effect text NOT NULL CHECK(effect IN('success','failed','unknown','refund_to_employer','refund_to_supplier','custody_return_to_employer')),
 amount numeric(24,2)NOT NULL CHECK(amount>0 AND amount<>'NaN'::numeric),paid_delta numeric(24,2)NOT NULL,released_delta numeric(24,2)NOT NULL CHECK(released_delta>=0),source_hash text NOT NULL,executed_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TRIGGER ty_pay_agency_reservation_keep BEFORE UPDATE OR DELETE ON ty_pay_agency_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE TRIGGER ty_pay_agency_effect_keep BEFORE UPDATE OR DELETE ON ty_pay_agency_effect FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE FUNCTION fn_ty_pay_agency_balance(reservation_key bigint)RETURNS jsonb LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT jsonb_build_object('settled',coalesce(sum(e.paid_delta),0)::text,'released',coalesce(sum(e.released_delta),0)::text,'held',greatest(0,r.amount-coalesce(sum(e.paid_delta),0)-coalesce(sum(e.released_delta),0))::text,'contradictory_events_review',greatest(0,coalesce(sum(e.paid_delta),0)+coalesce(sum(e.released_delta),0)-r.amount)::text)
 FROM public.ty_pay_agency_reservation r LEFT JOIN public.ty_pay_agency_effect e ON e.reservation_id=r.id WHERE r.id=reservation_key GROUP BY r.id;
$$;
CREATE OR REPLACE FUNCTION fn_ty_pay_fund_state(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE p public.ty_pay_fund_parent%ROWTYPE;src jsonb;target numeric;paid numeric;held numeric;a_paid numeric;a_held numeric;a_review numeric;
BEGIN
 SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=parent_key;IF p.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金父义务不存在';END IF;
 src:=public.fn_ty_pay_fund_source(p.group_id,p.person_id,p.actual_employer_key,p.actual_relationship_key,p.pay_subject_key,p.period,p.currency);target:=(src->>'target')::numeric;
 SELECT coalesce(sum(r.amount),0)INTO paid FROM public.ty_pay_payment_receipt r JOIN public.ty_pay_payment_order o ON o.id=r.order_id WHERE o.parent_id=p.id AND r.status='approved'AND r.kind='settled';
 SELECT coalesce(sum(greatest(0,o.amount-coalesce((SELECT sum(r.amount)FROM public.ty_pay_payment_receipt r WHERE r.order_id=o.id AND r.status='approved'AND r.kind='settled'),0))),0)INTO held FROM public.ty_pay_payment_order o WHERE o.parent_id=p.id AND o.status IN('approved','exported_unknown','partially_confirmed');
 SELECT coalesce(sum((s->>'settled')::numeric),0),coalesce(sum((s->>'held')::numeric),0),coalesce(sum((s->>'contradictory_events_review')::numeric),0)INTO a_paid,a_held,a_review FROM public.ty_pay_agency_reservation r CROSS JOIN LATERAL public.fn_ty_pay_agency_balance(r.id)s WHERE r.parent_id=p.id;
 paid:=paid+a_paid;held:=held+a_held;
 RETURN src||jsonb_build_object('settled',round(paid,2)::text,'held',round(held,2)::text,'available',round(greatest(0,target-paid-held),2)::text,'overpaid_review',round(greatest(0,paid-target),2)::text,'unresolved_overcommitment',round(greatest(0,paid+held-target),2)::text,'contradictory_events_review',round(a_review,2)::text,'bank_verified',false);
END;$$;
CREATE FUNCTION fn_ty_pay_agency_instruction_matches(instruction_key bigint,parent_key bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.ty_pay_agency_reservation r JOIN public.ty_wf_personal_instruction i ON i.id=r.instruction_id JOIN public.ty_pay_fund_parent p ON p.id=r.parent_id WHERE i.id=instruction_key AND p.id=parent_key AND i.group_id=p.group_id AND i.person_id=p.person_id AND i.period=p.period AND i.pay_subject_key=p.pay_subject_key AND i.currency=p.currency AND i.amount=r.amount AND i.source_hash=r.source_hash AND EXISTS(SELECT 1 FROM public.ty_pay_row w JOIN public.ty_pay_batch b ON b.id=w.batch_id JOIN public.ty_pay_config rc ON rc.id=w.relationship_config_id WHERE w.employment_id=i.employment_id AND w.person_id=p.person_id AND b.status='confirmed'AND rc.data->>'actual_employer_key'=p.actual_employer_key AND rc.data->>'actual_relationship_key'=p.actual_relationship_key));
$$;
CREATE FUNCTION fn_ty_pay_agency_receipt_applied(receipt_key bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$SELECT EXISTS(SELECT 1 FROM public.ty_pay_agency_effect e JOIN public.ty_wf_personal_receipt r ON r.id=e.receipt_id JOIN public.ty_pay_agency_reservation a ON a.id=e.reservation_id WHERE r.id=receipt_key AND r.instruction_id=a.instruction_id AND r.effect=e.effect AND r.amount=e.amount)$$;
CREATE FUNCTION fn_ty_pay_agency_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE i public.ty_wf_personal_instruction%ROWTYPE;m public.ty_wf_mandate%ROWTYPE;p public.ty_pay_fund_parent%ROWTYPE;r public.ty_wf_personal_receipt%ROWTYPE;orig public.ty_wf_personal_receipt%ROWTYPE;a public.ty_pay_agency_reservation%ROWTYPE;s jsonb;balance jsonb;paid numeric;released numeric;refunds numeric;custody numeric;returned numeric;expected_paid numeric:=0;expected_release numeric:=0;
BEGIN
 IF TG_TABLE_NAME='ty_pay_agency_reservation'THEN
  SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=NEW.parent_id FOR UPDATE;SELECT*INTO i FROM public.ty_wf_personal_instruction WHERE id=NEW.instruction_id FOR UPDATE;SELECT*INTO m FROM public.ty_wf_mandate WHERE id=i.mandate_id;
  IF p.id IS NULL OR i.id IS NULL OR m.id IS NULL OR i.status<>'approved'OR m.status<>'approved'OR m.group_id<>p.group_id OR m.company_id<>i.company_id OR m.person_id<>p.person_id OR m.employment_id<>i.employment_id OR m.supplier_id<>i.supplier_id OR m.contract_id<>i.contract_id OR m.valid_from>public.app_today()OR m.valid_to<=public.app_today()OR i.group_id<>p.group_id OR i.person_id<>p.person_id OR i.period<>p.period OR i.currency<>p.currency OR i.pay_subject_key<>p.pay_subject_key OR NEW.amount<>i.amount OR NEW.source_hash<>i.source_hash OR NOT public.fn_ty_pay_distinct_reviewer(i.created_by,i.approved_by,i.group_id,i.person_id)OR NOT public.fn_ty_pay_distinct_reviewer(m.created_by,m.approved_by,m.group_id,m.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发须真实已核同人主体授权、独立审批与尚未执行的指令，不凭供应商价格生成工资';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.ty_pay_row w JOIN public.ty_pay_batch b ON b.id=w.batch_id JOIN public.ty_pay_config rc ON rc.id=w.relationship_config_id WHERE w.employment_id=i.employment_id AND w.person_id=p.person_id AND b.status='confirmed'AND rc.data->>'actual_employer_key'=p.actual_employer_key AND rc.data->>'actual_relationship_key'=p.actual_relationship_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发实际法律关系不能换人或借另一雇主';END IF;
  s:=public.fn_ty_pay_fund_state(p.id);IF NEW.source_hash IS DISTINCT FROM s->>'source_hash'OR i.target_verified_amount<>(s->>'net_wage')::numeric OR NEW.amount>(s->'components'->'net_wage'->>'available')::numeric OR NEW.amount>(s->>'available')::numeric THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='工资来源已变或全部渠道余额不足，不能重复占款';END IF;
 ELSE
  SELECT*INTO a FROM public.ty_pay_agency_reservation WHERE id=NEW.reservation_id;SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=a.parent_id FOR UPDATE;SELECT*INTO r FROM public.ty_wf_personal_receipt WHERE id=NEW.receipt_id FOR UPDATE;SELECT*INTO i FROM public.ty_wf_personal_instruction WHERE id=a.instruction_id;
  IF NEW.source_hash IS DISTINCT FROM md5((to_jsonb(r)-'status'-'revision'-'applied_by'-'applied_at')::text)OR r.id IS NULL OR r.status<>'reviewed'OR r.instruction_id<>i.id OR r.group_id<>p.group_id OR r.currency<>p.currency OR NEW.effect<>r.effect OR NEW.amount<>r.amount OR NOT public.fn_ty_pay_distinct_reviewer(r.recorded_by,r.reviewed_by,p.group_id,p.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发结算只消费真实独立复核的原始逐人回执，不能凭客户端金额';END IF;
  balance:=public.fn_ty_pay_agency_balance(a.id);paid:=(balance->>'settled')::numeric;released:=(balance->>'released')::numeric;
  IF r.effect='success'THEN expected_paid:=r.amount;IF paid+r.amount>a.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='逐人累计到账超过原指令，须超付事件待核，不重复结算';END IF;
  ELSIF r.effect IN('refund_to_employer','refund_to_supplier','custody_return_to_employer')THEN
   SELECT*INTO orig FROM public.ty_wf_personal_receipt WHERE id=r.original_receipt_id;
   IF orig.id IS NULL OR orig.instruction_id<>i.id OR orig.currency<>r.currency OR orig.status<>'applied'OR orig.effect<>(CASE WHEN r.effect='custody_return_to_employer'THEN'failed'ELSE'success'END)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='返还必须反查同一指令真实原到账或未执行回执';END IF;
   SELECT coalesce(sum(e.amount),0)INTO refunds FROM public.ty_pay_agency_effect e JOIN public.ty_wf_personal_receipt x ON x.id=e.receipt_id WHERE x.original_receipt_id=orig.id;
   IF refunds+r.amount>orig.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原回执金额不能重复返还';END IF;
   IF r.effect<>'refund_to_supplier'AND coalesce((SELECT sum(l.amount)FROM public.ty_wf_fund_return_link l WHERE l.personal_receipt_id=r.id),0)<>r.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='返还雇主须同时有真实供应商AP退款关联，不能只按员工口头说已退';END IF;
   IF r.effect<>'custody_return_to_employer'THEN expected_paid:=-r.amount;IF paid<r.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未有足额逐人到账不能造负已结';END IF;END IF;
   IF r.effect<>'refund_to_supplier'THEN expected_release:=r.amount;END IF;
  ELSIF r.effect='failed'THEN
   s:=public.fn_ty_wf_custody_funding_state(i.id,NULL);IF s->>'ready'IS DISTINCT FROM'true'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商拨款/已核预付核销或返还来源待核，失败回执不能猜0释放';END IF;
   IF(s->>'transferred')::numeric+(s->>'active')::numeric<=(s->>'returned')::numeric THEN expected_release:=r.amount;END IF;
   IF expected_release>greatest(0,a.amount-paid-released)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未执行释放不得超过尚未结算占款';END IF;
  ELSIF r.effect<>'unknown'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未实现代发结果类型';END IF;
  IF NEW.paid_delta<>expected_paid OR NEW.released_delta<>expected_release THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发资金影响须由真实回执反推，不能客户端自写';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_agency_reserve_guard BEFORE INSERT ON ty_pay_agency_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_agency_guard();
CREATE TRIGGER ty_pay_agency_effect_guard BEFORE INSERT ON ty_pay_agency_effect FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_agency_guard();
-- Explicit component allocation prevents spending reimbursement as net wages.
ALTER TABLE ty_pay_payment_order ADD COLUMN net_wage_amount numeric(24,2)NOT NULL,ADD COLUMN reimbursement_amount numeric(24,2)NOT NULL,ADD COLUMN allocation_policy text NOT NULL DEFAULT'net_wage_first_then_reimbursement';
ALTER TABLE ty_pay_payment_order ADD CHECK(net_wage_amount>=0 AND reimbursement_amount>=0 AND net_wage_amount+reimbursement_amount=amount AND allocation_policy='net_wage_first_then_reimbursement');
ALTER TABLE ty_pay_payment_receipt ADD COLUMN net_wage_amount numeric(24,2)NOT NULL DEFAULT 0,ADD COLUMN reimbursement_amount numeric(24,2)NOT NULL DEFAULT 0;
ALTER TABLE ty_pay_payment_receipt ADD CHECK(net_wage_amount>=0 AND reimbursement_amount>=0 AND(status<>'approved'OR net_wage_amount+reimbursement_amount=amount));
CREATE FUNCTION fn_ty_pay_fund_components(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE p public.ty_pay_fund_parent%ROWTYPE;s jsonb;wpaid numeric;rpaid numeric;wheld numeric;rheld numeric;ap numeric;ah numeric;w numeric;r numeric;
BEGIN
 SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=parent_key;s:=public.fn_ty_pay_fund_source(p.group_id,p.person_id,p.actual_employer_key,p.actual_relationship_key,p.pay_subject_key,p.period,p.currency);w:=(s->>'net_wage')::numeric;r:=(s->>'reimbursement')::numeric;
 SELECT coalesce(sum(x.net_wage_amount),0),coalesce(sum(x.reimbursement_amount),0)INTO wpaid,rpaid FROM public.ty_pay_payment_receipt x JOIN public.ty_pay_payment_order o ON o.id=x.order_id WHERE o.parent_id=p.id AND x.status='approved'AND x.kind='settled';
 SELECT coalesce(sum(greatest(0,o.net_wage_amount-coalesce((SELECT sum(x.net_wage_amount)FROM public.ty_pay_payment_receipt x WHERE x.order_id=o.id AND x.status='approved'AND x.kind='settled'),0))),0),coalesce(sum(greatest(0,o.reimbursement_amount-coalesce((SELECT sum(x.reimbursement_amount)FROM public.ty_pay_payment_receipt x WHERE x.order_id=o.id AND x.status='approved'AND x.kind='settled'),0))),0)INTO wheld,rheld FROM public.ty_pay_payment_order o WHERE o.parent_id=p.id AND o.status IN('approved','exported_unknown','partially_confirmed');
 SELECT coalesce(sum((b->>'settled')::numeric),0),coalesce(sum((b->>'held')::numeric),0)INTO ap,ah FROM public.ty_pay_agency_reservation a CROSS JOIN LATERAL public.fn_ty_pay_agency_balance(a.id)b WHERE a.parent_id=p.id;wpaid:=wpaid+ap;wheld:=wheld+ah;
 RETURN jsonb_build_object('net_wage',jsonb_build_object('target',round(w,2)::text,'settled',round(wpaid,2)::text,'held',round(wheld,2)::text,'available',round(greatest(0,w-wpaid-wheld),2)::text,'overcommitment',round(greatest(0,wpaid+wheld-w),2)::text),'reimbursement',jsonb_build_object('target',round(r,2)::text,'settled',round(rpaid,2)::text,'held',round(rheld,2)::text,'available',round(greatest(0,r-rpaid-rheld),2)::text,'overcommitment',round(greatest(0,rpaid+rheld-r),2)::text));
END;$$;
ALTER FUNCTION fn_ty_pay_fund_state(bigint)RENAME TO fn_ty_pay_fund_state_precomponents;
CREATE FUNCTION fn_ty_pay_fund_state(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE s jsonb;c jsonb;overcommit numeric;BEGIN s:=public.fn_ty_pay_fund_state_precomponents(parent_key);c:=public.fn_ty_pay_fund_components(parent_key);overcommit:=greatest((s->>'unresolved_overcommitment')::numeric,(c->'net_wage'->>'overcommitment')::numeric,(c->'reimbursement'->>'overcommitment')::numeric);RETURN s||jsonb_build_object('components',c,'unresolved_overcommitment',round(overcommit,2)::text);END;$$;
CREATE FUNCTION fn_ty_pay_order_components_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE s jsonb;p public.ty_pay_fund_parent%ROWTYPE;BEGIN
 IF TG_OP='INSERT'OR OLD.status='draft'AND NEW.status='approved'THEN SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=NEW.parent_id FOR UPDATE;s:=public.fn_ty_pay_fund_components(p.id);IF NEW.net_wage_amount>(s->'net_wage'->>'available')::numeric OR NEW.reimbursement_amount>(s->'reimbursement'->>'available')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='净工资和报销须分别守可用余额，不能挪用另一分项重复付';END IF;END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_order_components_guard BEFORE INSERT OR UPDATE ON ty_pay_payment_order FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_order_components_guard();
-- Derive each partial receipt from the frozen independently approved order
-- allocation. This is an internal liability allocation, not a fabricated bank
-- statement claim about salary versus reimbursement.
DO $$DECLARE src text;BEGIN
 src:=pg_get_functiondef('public.fn_ty_pay_receipt_guard()'::regprocedure);
 IF position($n$ RETURN NEW;$n$IN src)=0 THEN RAISE EXCEPTION '227 receipt component drift';END IF;
 src:=replace(src,$n$ RETURN NEW;$n$,$n$ IF NEW.status='approved'THEN IF NEW.kind='settled'THEN SELECT coalesce(sum(x.net_wage_amount),0)INTO paid FROM public.ty_pay_payment_receipt x WHERE x.order_id=o.id AND x.status='approved'AND x.kind='settled'AND x.id<>NEW.id;NEW.net_wage_amount:=least(NEW.amount,greatest(0,o.net_wage_amount-paid));NEW.reimbursement_amount:=NEW.amount-NEW.net_wage_amount;ELSE NEW.net_wage_amount:=0;NEW.reimbursement_amount:=0;END IF;END IF;RETURN NEW;$n$);EXECUTE src;
END;$$;
CREATE FUNCTION fn_ty_pay_agency_custody_state(instruction_key bigint,exclude_payment_key bigint DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE i public.ty_wf_personal_instruction%ROWTYPE;a public.ty_pay_agency_reservation%ROWTYPE;p public.ty_pay_fund_parent%ROWTYPE;s jsonb;b jsonb;gross numeric;returned numeric;custody_still_held numeric;available numeric;
BEGIN
 SELECT*INTO i FROM public.ty_wf_personal_instruction WHERE id=instruction_key;SELECT*INTO a FROM public.ty_pay_agency_reservation WHERE instruction_id=i.id;SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=a.parent_id;
 IF i.id IS NULL OR a.id IS NULL THEN RETURN jsonb_build_object('ready',false,'available',NULL,'reason','missing_real_reservation');END IF;
 s:=public.fn_ty_pay_fund_state(p.id);b:=public.fn_ty_pay_agency_balance(a.id);
 IF i.source_hash IS DISTINCT FROM s->>'source_hash'OR(s->>'unresolved_overcommitment')::numeric>0 OR(s->>'contradictory_events_review')::numeric>0 THEN RETURN jsonb_build_object('ready',false,'available',NULL,'reason','wage_source_or_funds_changed');END IF;
 s:=public.fn_ty_wf_custody_funding_state(i.id,exclude_payment_key);IF s->>'ready'IS DISTINCT FROM'true'THEN RETURN jsonb_build_object('ready',false,'available',NULL,'reason',s->>'reason');END IF;
 gross:=(s->>'transferred')::numeric+(s->>'active')::numeric;returned:=(s->>'returned')::numeric;
 custody_still_held:=greatest(0,gross-returned-(b->>'settled')::numeric);available:=greatest(0,(b->>'held')::numeric-custody_still_held);
 RETURN jsonb_build_object('ready',true,'available',round(available,2)::text,'held',b->>'held','custody_active',round(custody_still_held,2)::text,'employee_settled',b->>'settled','supplier_advance_review_required',(b->>'settled')::numeric>greatest(0,gross-returned));
END;$$;
CREATE FUNCTION fn_ty_pay_synthetic_group(g bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$SELECT EXISTS(SELECT 1 FROM public.ty_audit WHERE action='seed'AND entity_kind='test_workspace'AND entity_id=g AND after_data->>'synthetic'='true'AND after_data->>'complete'='true')$$;
CREATE FUNCTION fn_ty_pay_synthetic_cash_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE g bigint;BEGIN
 IF TG_TABLE_NAME='ty_pay_payment_order'THEN SELECT group_id INTO g FROM public.ty_pay_fund_parent WHERE id=NEW.parent_id;ELSE g:=NEW.group_id;END IF;
 IF public.fn_ty_pay_synthetic_group(g)AND NOT NEW.demo_only THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='演示帐套仅支持演示资金与申报操作，不可改标正式办理';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pay_synthetic_recipient BEFORE INSERT OR UPDATE ON ty_pay_cash_recipient FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_synthetic_cash_guard();
CREATE TRIGGER ty_pay_synthetic_order BEFORE INSERT OR UPDATE ON ty_pay_payment_order FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_synthetic_cash_guard();
CREATE TRIGGER ty_pay_synthetic_filing BEFORE INSERT OR UPDATE ON ty_pay_filing FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_synthetic_cash_guard();

INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,p.resource_code,true,false FROM sys_role r CROSS JOIN sys_perm_resource p WHERE r.code IN('boss','ty_demo_boss')AND p.resource_code IN('payroll_payment','payroll_filing')ON CONFLICT DO NOTHING;

-- Opening cash facts are separate from wage targets. Missing records do not
-- establish that an employee has never been paid through an earlier channel.
CREATE TABLE ty_pay_fund_opening(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint NOT NULL REFERENCES ty_pay_fund_parent(id),
 kind text NOT NULL CHECK(kind IN('reviewed_fresh_start','external_reviewed_opening')),
 net_wage_paid numeric(24,2)NOT NULL CHECK(net_wage_paid>=0 AND net_wage_paid<>'NaN'::numeric),reimbursement_paid numeric(24,2)NOT NULL CHECK(reimbursement_paid>=0 AND reimbursement_paid<>'NaN'::numeric),
 net_wage_held numeric(24,2)NOT NULL CHECK(net_wage_held>=0 AND net_wage_held<>'NaN'::numeric),reimbursement_held numeric(24,2)NOT NULL CHECK(reimbursement_held>=0 AND reimbursement_held<>'NaN'::numeric),
 as_of timestamptz NOT NULL,evidence_ref text NOT NULL,document_hash text NOT NULL,source_hash text NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz
);
CREATE UNIQUE INDEX ty_pay_fund_one_opening ON ty_pay_fund_opening(parent_id)WHERE status='approved';
CREATE FUNCTION fn_ty_pay_fund_opening_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE p public.ty_pay_fund_parent;BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金期初原始事实保留，不得删除';END IF;
 SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=NEW.parent_id FOR UPDATE;
 IF NEW.kind='reviewed_fresh_start'AND(NEW.net_wage_paid+NEW.reimbursement_paid+NEW.net_wage_held+NEW.reimbursement_held)<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='首次未执行声明不得隐含已付或未知占款';END IF;
 IF length(NEW.document_hash)<16 OR length(NEW.evidence_ref)<4 OR NEW.as_of>clock_timestamp()THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金期初须有实际核对时点、凭据和摘要';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金期初必须从待核草稿登记';END IF;
 ELSE IF OLD.status<>'draft'OR NEW.status NOT IN('approved','rejected')OR NEW.revision<>OLD.revision+1 OR(to_jsonb(NEW)-ARRAY['status','revision','approved_by','approved_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','approved_by','approved_at'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金期初只能独立核定一次，原金额及凭据不得覆写';END IF;END IF;
 IF EXISTS(SELECT 1 FROM public.ty_pay_payment_order WHERE parent_id=p.id)OR EXISTS(SELECT 1 FROM public.ty_pay_agency_reservation WHERE parent_id=p.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已有资金业务不能再以期初覆盖；须登记对应原始结果及有据更正';END IF;
 IF NEW.status='approved'AND(NEW.approved_at IS NULL OR NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,p.group_id,p.person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='期初已付和未知占款须独立且非受益人核准';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_fund_opening_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_fund_opening FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_fund_opening_guard();
CREATE FUNCTION fn_ty_pay_fund_opening_state(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE o public.ty_pay_fund_opening;BEGIN SELECT*INTO o FROM public.ty_pay_fund_opening WHERE parent_id=parent_key AND status='approved';IF o.id IS NULL THEN RETURN jsonb_build_object('ready',false,'status','opening_pending_review');END IF;RETURN jsonb_build_object('ready',true,'id',o.id,'kind',o.kind,'status','approved','net_wage_paid',o.net_wage_paid::text,'reimbursement_paid',o.reimbursement_paid::text,'net_wage_held',o.net_wage_held::text,'reimbursement_held',o.reimbursement_held::text,'as_of',o.as_of,'source_hash',o.source_hash);END;$$;
ALTER FUNCTION fn_ty_pay_fund_components(bigint)RENAME TO fn_ty_pay_fund_components_preopening;
CREATE FUNCTION fn_ty_pay_fund_components(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE c jsonb;b jsonb;k text;s jsonb;paid numeric;held numeric;target numeric;BEGIN c:=public.fn_ty_pay_fund_components_preopening(parent_key);b:=public.fn_ty_pay_fund_opening_state(parent_key);FOREACH k IN ARRAY ARRAY['net_wage','reimbursement']LOOP s:=c->k;target:=(s->>'target')::numeric;IF b->>'ready'IS DISTINCT FROM'true'THEN s:=s||jsonb_build_object('settled',NULL,'held',NULL,'available',NULL,'overcommitment',NULL,'funding_baseline_status','opening_pending_review');ELSE paid:=(s->>'settled')::numeric+(b->>(k||'_paid'))::numeric;held:=(s->>'held')::numeric+(b->>(k||'_held'))::numeric;s:=s||jsonb_build_object('settled',round(paid,2)::text,'held',round(held,2)::text,'available',round(greatest(0,target-paid-held),2)::text,'overcommitment',round(greatest(0,paid+held-target),2)::text,'funding_baseline_status','approved');END IF;c:=jsonb_set(c,ARRAY[k],s);END LOOP;RETURN c;END;$$;
ALTER FUNCTION fn_ty_pay_fund_state(bigint)RENAME TO fn_ty_pay_fund_state_preopening;
CREATE FUNCTION fn_ty_pay_fund_state(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE s jsonb;c jsonb;b jsonb;paid numeric;held numeric;target numeric;BEGIN s:=public.fn_ty_pay_fund_state_preopening(parent_key);c:=public.fn_ty_pay_fund_components(parent_key);b:=public.fn_ty_pay_fund_opening_state(parent_key);IF b->>'ready'IS DISTINCT FROM'true'THEN RETURN s||jsonb_build_object('settled',NULL,'held',NULL,'available',NULL,'overpaid_review',NULL,'unresolved_overcommitment',NULL,'components',c,'funding_baseline_status','opening_pending_review','funding_baseline',b);END IF;paid:=(c->'net_wage'->>'settled')::numeric+(c->'reimbursement'->>'settled')::numeric;held:=(c->'net_wage'->>'held')::numeric+(c->'reimbursement'->>'held')::numeric;target:=(s->>'target')::numeric;RETURN s||jsonb_build_object('settled',round(paid,2)::text,'held',round(held,2)::text,'available',round(greatest(0,target-paid-held),2)::text,'overpaid_review',round(greatest(0,paid-target),2)::text,'unresolved_overcommitment',round(greatest(0,paid+held-target,(c->'net_wage'->>'overcommitment')::numeric,(c->'reimbursement'->>'overcommitment')::numeric),2)::text,'components',c,'funding_baseline_status','approved','funding_baseline',b);END;$$;
CREATE FUNCTION fn_ty_pay_require_fund_opening()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE required boolean:=true;BEGIN
 IF TG_TABLE_NAME='ty_pay_payment_order'AND TG_OP='UPDATE'THEN required:=OLD.status='draft'AND NEW.status='approved'OR OLD.status='approved'AND NEW.status='exported_unknown';END IF;
 IF required AND NOT EXISTS(SELECT 1 FROM public.ty_pay_fund_opening WHERE parent_id=NEW.parent_id AND status='approved')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='历史已付及未知资金期初尚未独立核定，不能按0可付或占款';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_order_opening BEFORE INSERT OR UPDATE ON ty_pay_payment_order FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_require_fund_opening();
CREATE TRIGGER ty_pay_agency_opening BEFORE INSERT ON ty_pay_agency_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_require_fund_opening();

-- Later reconciliation appends actual external results; it never edits the
-- approved opening or silently releases an unknown third-party instruction.
CREATE TABLE ty_pay_opening_event(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,opening_id bigint NOT NULL REFERENCES ty_pay_fund_opening(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 component text NOT NULL CHECK(component IN('net_wage','reimbursement')),kind text NOT NULL CHECK(kind IN('settled_from_held','release_held','returned_paid_to_employer','prior_paid_discovered')),
 amount numeric(24,2)NOT NULL CHECK(amount>0 AND amount<>'NaN'::numeric),issuer text NOT NULL,external_ref text NOT NULL,line_key text NOT NULL,document_hash text NOT NULL,evidence_ref text NOT NULL,
 source_kind text NOT NULL CHECK(source_kind IN('manually_reviewed_external_statement','demo_simulated')),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,source_hash text NOT NULL
);
CREATE TABLE ty_pay_cash_evidence_use(group_id bigint NOT NULL REFERENCES ty_group(id),issuer text NOT NULL,external_ref text NOT NULL,line_key text NOT NULL,owner_kind text NOT NULL CHECK(owner_kind IN('payment_receipt','opening_event')),owner_id bigint NOT NULL,PRIMARY KEY(group_id,issuer,external_ref,line_key));
CREATE FUNCTION fn_ty_pay_cash_evidence_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE owner text;x public.ty_pay_cash_evidence_use;BEGIN
 IF NEW.status<>'approved'OR TG_OP='UPDATE'AND OLD.status='approved'THEN RETURN NEW;END IF;owner:=CASE WHEN TG_TABLE_NAME='ty_pay_opening_event'THEN'opening_event'ELSE'payment_receipt'END;
 INSERT INTO public.ty_pay_cash_evidence_use(group_id,issuer,external_ref,line_key,owner_kind,owner_id)VALUES(NEW.group_id,NEW.issuer,NEW.external_ref,NEW.line_key,owner,NEW.id)ON CONFLICT DO NOTHING;
 SELECT*INTO x FROM public.ty_pay_cash_evidence_use WHERE group_id=NEW.group_id AND issuer=NEW.issuer AND external_ref=NEW.external_ref AND line_key=NEW.line_key;
 IF x.owner_kind<>owner OR x.owner_id<>NEW.id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一外部现金原件行已用于工资结果或期初对账，不能再造第二次已付/释放';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_cash_evidence_receipt BEFORE INSERT OR UPDATE ON ty_pay_payment_receipt FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_cash_evidence_guard();
CREATE TRIGGER ty_pay_cash_evidence_opening BEFORE INSERT OR UPDATE ON ty_pay_opening_event FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_cash_evidence_guard();
CREATE OR REPLACE FUNCTION fn_ty_pay_fund_opening_state(parent_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE o public.ty_pay_fund_opening;c text;paid numeric;held numeric;out jsonb;BEGIN
 SELECT*INTO o FROM public.ty_pay_fund_opening WHERE parent_id=parent_key AND status='approved';IF o.id IS NULL THEN RETURN jsonb_build_object('ready',false,'status','opening_pending_review');END IF;
 out:=jsonb_build_object('ready',true,'id',o.id,'kind',o.kind,'status','approved','as_of',o.as_of,'source_hash',o.source_hash);
 FOREACH c IN ARRAY ARRAY['net_wage','reimbursement']LOOP
  paid:=CASE WHEN c='net_wage'THEN o.net_wage_paid ELSE o.reimbursement_paid END;held:=CASE WHEN c='net_wage'THEN o.net_wage_held ELSE o.reimbursement_held END;
  SELECT paid+coalesce(sum(CASE kind WHEN'settled_from_held'THEN amount WHEN'prior_paid_discovered'THEN amount WHEN'returned_paid_to_employer'THEN-amount ELSE 0 END),0),held+coalesce(sum(CASE WHEN kind IN('settled_from_held','release_held')THEN-amount ELSE 0 END),0)INTO paid,held FROM public.ty_pay_opening_event WHERE opening_id=o.id AND component=c AND status='approved';
  out:=out||jsonb_build_object(c||'_paid',round(paid,2)::text,c||'_held',round(held,2)::text);
 END LOOP;RETURN out;END;$$;
CREATE FUNCTION fn_ty_pay_opening_event_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE o public.ty_pay_fund_opening;p public.ty_pay_fund_parent;s jsonb;BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='外部资金对账保留原件及更正，不得删除';END IF;
 SELECT*INTO o FROM public.ty_pay_fund_opening WHERE id=NEW.opening_id;SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=o.parent_id FOR UPDATE;
 IF o.status<>'approved'OR p.group_id<>NEW.group_id OR length(NEW.document_hash)<16 OR length(NEW.evidence_ref)<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='外部资金对账须同集团已核期初及真实可追溯原件';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='期初对账结果必须先登记待核';END IF;
 ELSE IF OLD.status<>'draft'OR NEW.status NOT IN('approved','rejected')OR NEW.revision<>OLD.revision+1 OR(to_jsonb(NEW)-ARRAY['status','revision','approved_by','approved_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','approved_by','approved_at'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='外部资金对账原事实不得覆写或重复应用';END IF;END IF;
 IF NEW.status='approved'THEN
  IF NEW.approved_at IS NULL OR NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,p.group_id,p.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金对账须独立自然人且非受益人核定';END IF;
  s:=public.fn_ty_pay_fund_opening_state(p.id);
  IF NEW.kind IN('settled_from_held','release_held')AND NEW.amount>(s->>(NEW.component||'_held'))::numeric OR NEW.kind='returned_paid_to_employer'AND NEW.amount>(s->>(NEW.component||'_paid'))::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='外部资金对账不得超原未知占款或已付可退余额';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_opening_event_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_opening_event FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_opening_event_guard();
CREATE TRIGGER ty_pay_cash_evidence_keep BEFORE UPDATE OR DELETE ON ty_pay_cash_evidence_use FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE FUNCTION fn_ty_pay_cash_evidence_owner()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF NEW.owner_kind='payment_receipt'AND NOT EXISTS(SELECT 1 FROM public.ty_pay_payment_receipt r WHERE r.id=NEW.owner_id AND r.group_id=NEW.group_id AND r.issuer=NEW.issuer AND r.external_ref=NEW.external_ref AND r.line_key=NEW.line_key)OR NEW.owner_kind='opening_event'AND NOT EXISTS(SELECT 1 FROM public.ty_pay_opening_event r WHERE r.id=NEW.owner_id AND r.group_id=NEW.group_id AND r.issuer=NEW.issuer AND r.external_ref=NEW.external_ref AND r.line_key=NEW.line_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='现金原件占用必须对应同集团同原件行的真实资金记录';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_cash_evidence_owner BEFORE INSERT ON ty_pay_cash_evidence_use FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_cash_evidence_owner();

-- Some local schemes (e.g. Shanghai housing fund) round each side to whole
-- yuan. The precision is an independently approved policy, not a UI hint.
CREATE FUNCTION fn_ty_pay_local_rounding_policy()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE d jsonb:=NEW.data;BEGIN
 IF NEW.kind='policy'AND d?'rounding_scale'THEN
  IF d->>'type'<>'CN_SOCIAL'OR jsonb_typeof(d->'rounding_scale')<>'number'OR(d->>'rounding_scale')::numeric NOT IN(0,2)OR(d->>'rounding_scale')::numeric=0 AND(d->>'employee_code'<>'CN_EMP_HOUSING_FUND'OR d->>'employer_code'<>'CN_ER_HOUSING_FUND')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供款舍入须为已支持的明确政策；整元只适用于已核住房公积金配对';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_local_rounding_policy BEFORE INSERT OR UPDATE ON ty_pay_stat_config FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_local_rounding_policy();
ALTER FUNCTION fn_ty_pay_stat_math(jsonb,text)RENAME TO fn_ty_pay_stat_math_pre227rounding;
CREATE FUNCTION fn_ty_pay_stat_math(c jsonb,component text)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$DECLARE p jsonb:=c->'policy'->'data';v jsonb:=c->'period_parameters';side text;base numeric;target numeric;BEGIN
 IF c->>'type'<>'CN_SOCIAL'OR p->>'rounding_scale'IS DISTINCT FROM'0'THEN RETURN public.fn_ty_pay_stat_math_pre227rounding(c,component);END IF;
 IF component=p->>'employee_code'THEN side:='employee';ELSIF component=p->>'employer_code'THEN side:='employer';ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='住房公积金组件不属于已核配对';END IF;
 IF jsonb_typeof(v->(side||'_eligible'))IS DISTINCT FROM'boolean'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='住房公积金适用资格待核';END IF;
 IF NOT(v->>(side||'_eligible'))::boolean THEN RETURN jsonb_build_object('state','not_applicable','target',NULL);END IF;
 base:=least((p->>'upper')::numeric,greatest((p->>'lower')::numeric,(v->>'declared_base')::numeric));target:=round(round(base*(p->>(side||'_rate'))::numeric,0)+(v->>(side||'_arrears'))::numeric,2);
 RETURN jsonb_build_object('state','calculated','target',target::text,'rounding_scale',0,'rounding_order','base_contribution_half_up_whole_yuan_then_reviewed_arrears_fen');END;$$;

-- Original evidence is encrypted by224; typed links bind the real business
-- owner, never ty_pf_attachment.owner_id (which is the uploading operator).
CREATE TABLE ty_pay_document_link(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 order_id bigint REFERENCES ty_pay_payment_order(id),receipt_id bigint REFERENCES ty_pay_payment_receipt(id),opening_id bigint REFERENCES ty_pay_fund_opening(id),opening_event_id bigint REFERENCES ty_pay_opening_event(id),filing_id bigint REFERENCES ty_pay_filing(id),filing_event_id bigint REFERENCES ty_pay_filing_event(id),
 owner_kind text NOT NULL CHECK(owner_kind IN('payroll_payment','payroll_filing')),owner_key text NOT NULL,field_key text NOT NULL DEFAULT'evidence_file'CHECK(field_key='evidence_file'),
 attachment_id bigint NOT NULL REFERENCES ty_pf_attachment(id),evidence_role text NOT NULL CHECK(evidence_role IN('original_basis','supplemental')),created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(num_nonnulls(order_id,receipt_id,opening_id,opening_event_id,filing_id,filing_event_id)=1),UNIQUE(owner_kind,owner_key,attachment_id,evidence_role)
);
CREATE FUNCTION fn_ty_pay_document_link_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE a public.ty_pf_attachment;p public.ty_pay_fund_parent;g bigint;c bigint;k text;expected_owner text;basis_hash text;BEGIN
 SELECT*INTO a FROM public.ty_pf_attachment WHERE id=NEW.attachment_id;
 IF NEW.order_id IS NOT NULL THEN SELECT f.*INTO p FROM public.ty_pay_fund_parent f JOIN public.ty_pay_payment_order o ON o.parent_id=f.id WHERE o.id=NEW.order_id;k:='order:'||NEW.order_id;
 ELSIF NEW.receipt_id IS NOT NULL THEN SELECT f.*INTO p FROM public.ty_pay_fund_parent f JOIN public.ty_pay_payment_order o ON o.parent_id=f.id JOIN public.ty_pay_payment_receipt r ON r.order_id=o.id WHERE r.id=NEW.receipt_id;SELECT document_hash INTO basis_hash FROM public.ty_pay_payment_receipt WHERE id=NEW.receipt_id;k:='receipt:'||NEW.receipt_id;
 ELSIF NEW.opening_id IS NOT NULL THEN SELECT f.*INTO p FROM public.ty_pay_fund_parent f JOIN public.ty_pay_fund_opening x ON x.parent_id=f.id WHERE x.id=NEW.opening_id;SELECT document_hash INTO basis_hash FROM public.ty_pay_fund_opening WHERE id=NEW.opening_id;k:='opening:'||NEW.opening_id;
 ELSIF NEW.opening_event_id IS NOT NULL THEN SELECT f.*INTO p FROM public.ty_pay_fund_parent f JOIN public.ty_pay_fund_opening x ON x.parent_id=f.id JOIN public.ty_pay_opening_event e ON e.opening_id=x.id WHERE e.id=NEW.opening_event_id;SELECT document_hash INTO basis_hash FROM public.ty_pay_opening_event WHERE id=NEW.opening_event_id;k:='opening_event:'||NEW.opening_event_id;
 ELSIF NEW.filing_id IS NOT NULL THEN SELECT group_id,company_id INTO g,c FROM public.ty_pay_filing WHERE id=NEW.filing_id;k:='filing:'||NEW.filing_id;
 ELSE SELECT f.group_id,f.company_id INTO g,c FROM public.ty_pay_filing f JOIN public.ty_pay_filing_event e ON e.filing_id=f.id WHERE e.id=NEW.filing_event_id;SELECT document_hash INTO basis_hash FROM public.ty_pay_filing_event WHERE id=NEW.filing_event_id;k:='filing_event:'||NEW.filing_event_id;END IF;
 IF p.id IS NOT NULL THEN g:=p.group_id;c:=p.company_id;expected_owner:='payroll_payment';ELSE expected_owner:='payroll_filing';END IF;
 IF g IS NULL OR c IS NULL OR NEW.group_id<>g OR NEW.company_id<>c OR NEW.owner_kind<>expected_owner OR NEW.owner_key<>k OR a.owner_kind<>expected_owner OR a.owner_key<>k OR a.group_id<>g OR a.company_id IS DISTINCT FROM c OR a.field_key<>NEW.field_key OR a.status<>'ready'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='薪酬原件须属于真实同集团同公司同业务事项，不能借用表单或其他人的附件';END IF;
 IF NEW.evidence_role='original_basis'AND(basis_hash IS NULL OR basis_hash<>a.sha256)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原始依据附件摘要须等于已登记原件摘要；补充材料不能冒充原依据';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_document_link_guard BEFORE INSERT ON ty_pay_document_link FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_document_link_guard();
CREATE TRIGGER ty_pay_document_link_keep BEFORE UPDATE OR DELETE ON ty_pay_document_link FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();

-- Workflow214 uses a bigint subject id. A typed registry preserves separate
-- source tables without coercing the shared workflow column to text/JSON.
CREATE TABLE ty_pay_finance_subject(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint REFERENCES ty_person(id),
 kind text NOT NULL CHECK(kind IN('recipient','opening','opening_event','order','receipt','filing','filing_event')),source_id bigint NOT NULL,
 recipient_id bigint REFERENCES ty_pay_cash_recipient(id),opening_id bigint REFERENCES ty_pay_fund_opening(id),opening_event_id bigint REFERENCES ty_pay_opening_event(id),order_id bigint REFERENCES ty_pay_payment_order(id),receipt_id bigint REFERENCES ty_pay_payment_receipt(id),filing_id bigint REFERENCES ty_pay_filing(id),filing_event_id bigint REFERENCES ty_pay_filing_event(id),
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(kind,source_id),
 CHECK(num_nonnulls(recipient_id,opening_id,opening_event_id,order_id,receipt_id,filing_id,filing_event_id)=1),
 CHECK(kind='recipient'AND recipient_id IS NOT NULL AND recipient_id=source_id OR kind='opening'AND opening_id IS NOT NULL AND opening_id=source_id OR kind='opening_event'AND opening_event_id IS NOT NULL AND opening_event_id=source_id OR kind='order'AND order_id IS NOT NULL AND order_id=source_id OR kind='receipt'AND receipt_id IS NOT NULL AND receipt_id=source_id OR kind='filing'AND filing_id IS NOT NULL AND filing_id=source_id OR kind='filing_event'AND filing_event_id IS NOT NULL AND filing_event_id=source_id)
);
CREATE FUNCTION fn_ty_pay_finance_scope(k text,source_key bigint)RETURNS TABLE(group_id bigint,company_id bigint,person_id bigint,created_by bigint)LANGUAGE plpgsql STABLE SET search_path=''AS $$BEGIN
 IF k='recipient'THEN RETURN QUERY SELECT r.group_id,r.company_id,r.person_id,r.created_by FROM public.ty_pay_cash_recipient r WHERE r.id=source_key;
 ELSIF k='order'THEN RETURN QUERY SELECT p.group_id,p.company_id,p.person_id,r.created_by FROM public.ty_pay_payment_order r JOIN public.ty_pay_fund_parent p ON p.id=r.parent_id WHERE r.id=source_key;
 ELSIF k='receipt'THEN RETURN QUERY SELECT p.group_id,p.company_id,p.person_id,r.created_by FROM public.ty_pay_payment_receipt r JOIN public.ty_pay_payment_order o ON o.id=r.order_id JOIN public.ty_pay_fund_parent p ON p.id=o.parent_id WHERE r.id=source_key;
 ELSIF k='opening'THEN RETURN QUERY SELECT p.group_id,p.company_id,p.person_id,r.created_by FROM public.ty_pay_fund_opening r JOIN public.ty_pay_fund_parent p ON p.id=r.parent_id WHERE r.id=source_key;
 ELSIF k='opening_event'THEN RETURN QUERY SELECT p.group_id,p.company_id,p.person_id,r.created_by FROM public.ty_pay_opening_event r JOIN public.ty_pay_fund_opening o ON o.id=r.opening_id JOIN public.ty_pay_fund_parent p ON p.id=o.parent_id WHERE r.id=source_key;
 ELSIF k='filing'THEN RETURN QUERY SELECT r.group_id,r.company_id,NULL::bigint,r.created_by FROM public.ty_pay_filing r WHERE r.id=source_key;
 ELSIF k='filing_event'THEN RETURN QUERY SELECT p.group_id,p.company_id,NULL::bigint,r.created_by FROM public.ty_pay_filing_event r JOIN public.ty_pay_filing p ON p.id=r.filing_id WHERE r.id=source_key;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未登记资金审批来源类型';END IF;END;$$;
CREATE FUNCTION fn_ty_pay_finance_subject_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE s record;BEGIN
 SELECT*INTO s FROM public.fn_ty_pay_finance_scope(NEW.kind,NEW.source_id);IF s.group_id IS NULL OR ROW(NEW.group_id,NEW.company_id,NEW.person_id,NEW.created_by)IS DISTINCT FROM ROW(s.group_id,s.company_id,s.person_id,s.created_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金审批主体须来自同公司同永久人员的真实固定类型单据';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_finance_subject_guard BEFORE INSERT ON ty_pay_finance_subject FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_subject_guard();
CREATE TRIGGER ty_pay_finance_subject_keep BEFORE UPDATE OR DELETE ON ty_pay_finance_subject FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
CREATE FUNCTION fn_ty_pay_finance_register()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE k text:=TG_ARGV[0];s record;column_key text;BEGIN
 SELECT*INTO s FROM public.fn_ty_pay_finance_scope(k,NEW.id);column_key:=k||'_id';
 EXECUTE format('INSERT INTO public.ty_pay_finance_subject(group_id,company_id,person_id,kind,source_id,%I,created_by)VALUES($1,$2,$3,$4,$5,$5,$6)',column_key)USING s.group_id,s.company_id,s.person_id,k,NEW.id,s.created_by;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_finance_register_recipient AFTER INSERT ON ty_pay_cash_recipient FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_register('recipient');
CREATE TRIGGER ty_pay_finance_register_order AFTER INSERT ON ty_pay_payment_order FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_register('order');
CREATE TRIGGER ty_pay_finance_register_receipt AFTER INSERT ON ty_pay_payment_receipt FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_register('receipt');
CREATE TRIGGER ty_pay_finance_register_opening AFTER INSERT ON ty_pay_fund_opening FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_register('opening');
CREATE TRIGGER ty_pay_finance_register_opening_event AFTER INSERT ON ty_pay_opening_event FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_register('opening_event');
CREATE TRIGGER ty_pay_finance_register_filing AFTER INSERT ON ty_pay_filing FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_register('filing');
CREATE TRIGGER ty_pay_finance_register_filing_event AFTER INSERT ON ty_pay_filing_event FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_register('filing_event');
CREATE TABLE ty_pay_finance_approval_receipt(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,subject_id bigint NOT NULL REFERENCES ty_pay_finance_subject(id),instance_id bigint NOT NULL UNIQUE REFERENCES ty_workflow_instance(id),
 original_requester_id bigint NOT NULL REFERENCES sys_account(id),approved_by bigint NOT NULL REFERENCES sys_account(id),execution_actor_id bigint NOT NULL REFERENCES sys_account(id),source_hash text NOT NULL,executed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE FUNCTION fn_ty_pay_finance_receipt_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE w public.ty_workflow_instance;s public.ty_pay_finance_subject;actual_reviewer bigint;actual_status text;source_table text;BEGIN
 SELECT*INTO w FROM public.ty_workflow_instance WHERE id=NEW.instance_id;SELECT*INTO s FROM public.ty_pay_finance_subject WHERE id=NEW.subject_id;
 IF w.subject_type<>'payroll_finance'OR w.subject_id<>s.id OR w.group_id<>s.group_id OR w.company_id IS DISTINCT FROM s.company_id OR w.status<>'approved'OR w.source_hash<>NEW.source_hash OR w.applicant_id<>NEW.original_requester_id OR w.last_approver_id<>NEW.approved_by OR NOT public.fn_ty_pay_distinct_reviewer(NEW.original_requester_id,NEW.approved_by,s.group_id,s.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金审批回执须对应真实独立批准、冻结来源及原申请人';END IF;
 source_table:=CASE s.kind WHEN'recipient'THEN'ty_pay_cash_recipient'WHEN'opening'THEN'ty_pay_fund_opening'WHEN'opening_event'THEN'ty_pay_opening_event'WHEN'order'THEN'ty_pay_payment_order'WHEN'receipt'THEN'ty_pay_payment_receipt'WHEN'filing'THEN'ty_pay_filing'WHEN'filing_event'THEN'ty_pay_filing_event'END;
 EXECUTE format('SELECT %I,status FROM public.%I WHERE id=$1',CASE WHEN s.kind='filing'THEN'reviewed_by'ELSE'approved_by'END,source_table)INTO actual_reviewer,actual_status USING s.source_id;
 IF actual_reviewer IS DISTINCT FROM NEW.approved_by OR actual_status IS DISTINCT FROM(CASE WHEN s.kind='filing'THEN'reviewed'ELSE'approved'END)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='流程回执不能冒充未生效领域核准或另一真实复核人';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_finance_receipt_guard BEFORE INSERT ON ty_pay_finance_approval_receipt FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_finance_receipt_guard();
CREATE TRIGGER ty_pay_finance_receipt_keep BEFORE UPDATE OR DELETE ON ty_pay_finance_approval_receipt FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();

-- A simulated acknowledgement must never settle a production wage parent.
-- Mode is derived from the actual confirmed wage rules, not caller flags.
ALTER TABLE ty_pay_fund_parent ADD COLUMN demo_only boolean NOT NULL DEFAULT false;
CREATE FUNCTION fn_ty_pay_fund_mode(g bigint,pe bigint,employer text,relationship_key text,payer text,period_key date,ccy text)RETURNS text LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE n integer;bad_count integer;all_demo boolean;any_demo boolean;BEGIN
 IF public.fn_ty_pay_synthetic_group(g)THEN RETURN'demo';END IF;
 SELECT count(*),count(*)FILTER(WHERE rule.data?'synthetic_only'AND jsonb_typeof(rule.data->'synthetic_only')<>'boolean'),bool_and(coalesce((rule.data->'synthetic_only')='true'::jsonb,false)),bool_or(coalesce((rule.data->'synthetic_only')='true'::jsonb,false))INTO n,bad_count,all_demo,any_demo FROM public.ty_pay_row r JOIN public.ty_pay_batch b ON b.id=r.batch_id JOIN public.ty_pay_config rc ON rc.id=r.relationship_config_id JOIN public.ty_pay_config rule ON rule.id=b.rulebook_id WHERE r.group_id=g AND r.person_id=pe AND rc.data->>'actual_employer_key'=employer AND rc.data->>'actual_relationship_key'=relationship_key AND b.period=period_key AND b.pay_subject_key=payer AND b.currency=ccy AND b.status='confirmed';
 IF n=0 OR bad_count>0 THEN RETURN'unknown';END IF;IF all_demo THEN RETURN'demo';END IF;IF any_demo THEN RETURN'mixed';END IF;RETURN'production';END;$$;
CREATE FUNCTION fn_ty_pay_fund_mode_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE p public.ty_pay_fund_parent;r public.ty_pay_cash_recipient;m text;BEGIN
 IF TG_TABLE_NAME='ty_pay_fund_parent'THEN
  m:=public.fn_ty_pay_fund_mode(NEW.group_id,NEW.person_id,NEW.actual_employer_key,NEW.actual_relationship_key,NEW.pay_subject_key,NEW.period,NEW.currency);
  IF m NOT IN('demo','production')OR jsonb_array_length(public.fn_ty_pay_fund_source(NEW.group_id,NEW.person_id,NEW.actual_employer_key,NEW.actual_relationship_key,NEW.pay_subject_key,NEW.period,NEW.currency)->'source_refs')=0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金源的演示/正式模式未知或混用，不能建立可执行资金父账';END IF;NEW.demo_only:=m='demo';RETURN NEW;
 END IF;
 SELECT*INTO p FROM public.ty_pay_fund_parent WHERE id=NEW.parent_id;m:=public.fn_ty_pay_fund_mode(p.group_id,p.person_id,p.actual_employer_key,p.actual_relationship_key,p.pay_subject_key,p.period,p.currency);
 IF m NOT IN('demo','production')OR p.demo_only IS DISTINCT FROM(m='demo')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资金来源模式已混用或改变，先核对演示/正式来源，不得继续执行';END IF;
 IF TG_TABLE_NAME='ty_pay_payment_order'THEN SELECT*INTO r FROM public.ty_pay_cash_recipient WHERE id=NEW.recipient_id;IF NEW.demo_only IS DISTINCT FROM p.demo_only OR r.demo_only IS DISTINCT FROM p.demo_only THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='收款资料和指令不能把演示工资改作正式付款或反向混用';END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_fund_mode BEFORE INSERT ON ty_pay_fund_parent FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_fund_mode_guard();
CREATE TRIGGER ty_pay_order_mode BEFORE INSERT ON ty_pay_payment_order FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_fund_mode_guard();
CREATE TRIGGER ty_pay_order_mode_execute BEFORE UPDATE ON ty_pay_payment_order FOR EACH ROW WHEN(NEW.status IN('approved','exported_unknown')AND NEW.status IS DISTINCT FROM OLD.status)EXECUTE FUNCTION fn_ty_pay_fund_mode_guard();
CREATE TRIGGER ty_pay_agency_mode BEFORE INSERT ON ty_pay_agency_reservation FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_fund_mode_guard();
CREATE FUNCTION fn_ty_pay_opening_event_mode()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE p public.ty_pay_fund_parent;BEGIN SELECT f.*INTO p FROM public.ty_pay_fund_parent f JOIN public.ty_pay_fund_opening o ON o.parent_id=f.id WHERE o.id=NEW.opening_id;IF p.demo_only IS DISTINCT FROM(NEW.source_kind='demo_simulated')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='模拟外部资金结果与正式已付/未知期初不得混账';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_opening_event_mode BEFORE INSERT OR UPDATE ON ty_pay_opening_event FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_opening_event_mode();
CREATE FUNCTION fn_ty_pay_agency_effect_mode()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE p public.ty_pay_fund_parent;r public.ty_wf_personal_receipt;BEGIN SELECT f.*INTO p FROM public.ty_pay_fund_parent f JOIN public.ty_pay_agency_reservation a ON a.parent_id=f.id WHERE a.id=NEW.reservation_id;SELECT*INTO r FROM public.ty_wf_personal_receipt WHERE id=NEW.receipt_id;IF p.demo_only IS DISTINCT FROM(r.source_kind='synthetic_demo_only')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商模拟个人结果与正式工资资金不得混账';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_agency_effect_mode BEFORE INSERT ON ty_pay_agency_effect FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_agency_effect_mode();

CREATE FUNCTION fn_ty_pay_filing_mode(snapshot_value jsonb)RETURNS text LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE n integer;bad_count integer;all_demo boolean;any_demo boolean;BEGIN
 IF public.fn_ty_pay_synthetic_group((snapshot_value->>'group_id')::bigint)THEN RETURN'demo';END IF;
 SELECT count(*),count(*)FILTER(WHERE rule.data?'synthetic_only'AND jsonb_typeof(rule.data->'synthetic_only')<>'boolean'),bool_and(coalesce(rule.data->'synthetic_only'='true'::jsonb,false)),bool_or(coalesce(rule.data->'synthetic_only'='true'::jsonb,false))INTO n,bad_count,all_demo,any_demo FROM(SELECT DISTINCT(x->>'batch_id')::bigint batch_id FROM jsonb_array_elements(snapshot_value->'rows')x)refs JOIN public.ty_pay_batch b ON b.id=refs.batch_id JOIN public.ty_pay_config rule ON rule.id=b.rulebook_id;
 IF n=0 OR bad_count>0 THEN RETURN'unknown';END IF;IF all_demo THEN RETURN'demo';END IF;IF any_demo THEN RETURN'mixed';END IF;RETURN'production';END;$$;
CREATE FUNCTION fn_ty_pay_filing_mode_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE m text;BEGIN m:=public.fn_ty_pay_filing_mode(NEW.snapshot);IF m NOT IN('demo','production')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报模式不能混用演示与正式工资来源';END IF;IF TG_OP='INSERT'THEN NEW.demo_only:=m='demo';ELSIF NEW.demo_only IS DISTINCT FROM(m='demo')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报模式须与确切来源一致，不能改标';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_filing_mode BEFORE INSERT OR UPDATE ON ty_pay_filing FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_filing_mode_guard();

-- Customer-reviewed target layouts are configuration, not an institution's
-- acceptance. Frozen outputs retain the exact format/registration/identity
-- versions and encrypted original bytes; no template executes code.
CREATE TABLE ty_pay_finance_format(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,kind text NOT NULL CHECK(kind IN('BANK_PAYMENT','CN_IIT','CN_SOCIAL','CN_HOUSING','HK_MPF','HK_IR56')),system text NOT NULL CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),currency text NOT NULL CHECK(currency IN('CNY','HKD')),stable_key text NOT NULL,version int NOT NULL CHECK(version>0),
 data jsonb NOT NULL,source_hash text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','revoked')),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),UNIQUE(group_id,company_id,kind,stable_key,version),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE TABLE ty_pay_finance_registration(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,kind text NOT NULL,system text NOT NULL,currency text NOT NULL,subject_key text NOT NULL,institution_code text NOT NULL,version int NOT NULL CHECK(version>0),demo_only boolean NOT NULL,data_cipher jsonb NOT NULL,fingerprint text NOT NULL,masked_identifier text NOT NULL,evidence_ref text NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','revoked')),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),UNIQUE(group_id,company_id,kind,subject_key,version),CHECK(kind IN('BANK_PAYMENT','CN_IIT','CN_SOCIAL','CN_HOUSING','HK_MPF','HK_IR56')),CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),CHECK(currency IN('CNY','HKD')),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE TABLE ty_pay_filing_identity(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,person_id bigint NOT NULL,employment_id bigint NOT NULL,actual_employer_key text NOT NULL,system text NOT NULL,currency text NOT NULL,identity_type text NOT NULL CHECK(identity_type IN('CN_NATIONAL_ID','HKID','PASSPORT','EMPLOYEE_REFERENCE')),version int NOT NULL CHECK(version>0),demo_only boolean NOT NULL,data_cipher jsonb NOT NULL,fingerprint text NOT NULL,masked_identifier text NOT NULL,evidence_ref text NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','revoked')),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_at timestamptz,
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),UNIQUE(employment_id,actual_employer_key,system,version),CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),CHECK(currency IN('CNY','HKD')),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE FUNCTION fn_ty_pay_format_config_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE beneficiary bigint;BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已留存文件配置不可删除';END IF;
 IF TG_TABLE_NAME='ty_pay_filing_identity'THEN beneficiary:=NEW.person_id;IF NOT EXISTS(SELECT 1 FROM public.ty_employment e WHERE e.id=NEW.employment_id AND e.person_id=NEW.person_id AND e.company_id=NEW.company_id AND e.group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报身份须对应同人真实雇佣，不按姓名匹配';END IF;END IF;
 IF TG_OP='INSERT'AND NEW.status<>'draft'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='文件配置须先建立草稿再独立核准';END IF;
 IF TG_OP='UPDATE'THEN
  IF to_jsonb(NEW)-'status'-'approved_by'-'approved_at'IS DISTINCT FROM to_jsonb(OLD)-'status'-'approved_by'-'approved_at'OR NOT(OLD.status='draft'AND NEW.status='approved'OR OLD.status='approved'AND NEW.status='revoked')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='文件配置修订须新版本，不覆盖原格式/身份/登记';END IF;
  IF OLD.status='draft'AND NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,NEW.group_id,beneficiary)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='文件配置须独立自然人且非受益人核准';END IF;
  IF OLD.status='approved'AND ROW(NEW.approved_by,NEW.approved_at)IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原文件核准历史不可改写';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_format_config_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_finance_format FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_format_config_guard();
CREATE TRIGGER ty_pay_registration_config_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_finance_registration FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_format_config_guard();
CREATE TRIGGER ty_pay_filing_identity_config_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_pay_filing_identity FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_format_config_guard();
CREATE TABLE ty_pay_export_artifact(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL,company_id bigint NOT NULL,kind text NOT NULL,order_id bigint UNIQUE REFERENCES ty_pay_payment_order(id),filing_id bigint UNIQUE REFERENCES ty_pay_filing(id),format_id bigint NOT NULL REFERENCES ty_pay_finance_format(id),registration_id bigint NOT NULL REFERENCES ty_pay_finance_registration(id),identity_ids bigint[]NOT NULL DEFAULT'{}',attachment_id bigint NOT NULL UNIQUE REFERENCES ty_pf_attachment(id),sha256 text NOT NULL,byte_length int NOT NULL CHECK(byte_length>0 AND byte_length<=8388608),source_hash text NOT NULL,format_hash text NOT NULL,registration_fingerprint text NOT NULL,row_count int NOT NULL CHECK(row_count>0),demo_only boolean NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),CHECK(num_nonnulls(order_id,filing_id)=1),CHECK((kind='BANK_PAYMENT')=(order_id IS NOT NULL))
);
CREATE FUNCTION fn_ty_pay_export_artifact_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE f public.ty_pay_finance_format;r public.ty_pay_finance_registration;a public.ty_pf_attachment;sc record;identity_row public.ty_pay_filing_identity;source_row jsonb;subject_field text;BEGIN
 SELECT*INTO f FROM public.ty_pay_finance_format WHERE id=NEW.format_id;SELECT*INTO r FROM public.ty_pay_finance_registration WHERE id=NEW.registration_id;SELECT*INTO a FROM public.ty_pf_attachment WHERE id=NEW.attachment_id;
 IF f.status<>'approved'OR r.status<>'approved'OR f.kind<>NEW.kind OR r.kind<>NEW.kind OR f.group_id<>NEW.group_id OR r.group_id<>NEW.group_id OR f.company_id<>NEW.company_id OR r.company_id<>NEW.company_id OR f.system<>r.system OR f.currency<>r.currency OR NEW.format_hash<>f.source_hash OR NEW.registration_fingerprint<>r.fingerprint OR NEW.demo_only<>r.demo_only THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='输出须冻结同范围已核布局及真实登记，不借另一模板';END IF;
 IF NEW.order_id IS NOT NULL THEN
  SELECT 'BANK_PAYMENT'::text kind,p.group_id,p.company_id,p.currency,p.demo_only,p.pay_subject_key subject_key,o.source_hash,o.status INTO sc FROM public.ty_pay_payment_order o JOIN public.ty_pay_fund_parent p ON p.id=o.parent_id WHERE o.id=NEW.order_id;
  IF sc.status<>'approved'OR r.subject_key IS DISTINCT FROM sc.subject_key OR cardinality(NEW.identity_ids)>0 OR a.owner_kind<>'payroll_payment'OR a.owner_key<>'order:'||NEW.order_id::text THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='银行文件须对应尚未外发已核付款及确切原件所属';END IF;
 ELSE
  SELECT kind,group_id,company_id,CASE system WHEN'CN_PAYROLL'THEN'CNY'ELSE'HKD'END currency,demo_only,source_hash,status INTO sc FROM public.ty_pay_filing WHERE id=NEW.filing_id;
  IF sc.status<>'reviewed'OR a.owner_kind<>'payroll_filing'OR a.owner_key<>'filing:'||NEW.filing_id::text THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='机构文件须对应已核申报底稿及确切原件所属';END IF;
  IF cardinality(NEW.identity_ids)<>(SELECT count(DISTINCT id)FROM public.ty_pay_filing_identity WHERE id=ANY(NEW.identity_ids))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实名引用不可缺失或重复';END IF;
  subject_field:=CASE WHEN NEW.kind IN('CN_IIT','HK_IR56')THEN'tax_subject_key'ELSE'contribution_subject_key'END;
  FOR source_row IN SELECT x FROM public.ty_pay_filing f0 CROSS JOIN LATERAL jsonb_array_elements(f0.snapshot->'rows')x WHERE f0.id=NEW.filing_id LOOP
   IF source_row->>subject_field IS DISTINCT FROM r.subject_key OR NOT EXISTS(SELECT 1 FROM public.ty_pay_filing_identity i WHERE i.id=ANY(NEW.identity_ids)AND i.employment_id=(source_row->>'employment_id')::bigint AND i.person_id=(source_row->>'person_id')::bigint AND i.actual_employer_key=source_row->>'actual_employer_key')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='机构主体及每份真实关系的身份必须完整对应，不借名或漏人';END IF;
  END LOOP;
  FOR identity_row IN SELECT*FROM public.ty_pay_filing_identity WHERE id=ANY(NEW.identity_ids)LOOP IF identity_row.status<>'approved'OR identity_row.group_id<>NEW.group_id OR identity_row.company_id<>NEW.company_id OR identity_row.demo_only<>NEW.demo_only OR identity_row.system<>f.system OR identity_row.currency<>f.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申报人员身份须当前同范围已核版本';END IF;END LOOP;
 END IF;
 IF sc.kind<>NEW.kind OR sc.group_id<>NEW.group_id OR sc.company_id<>NEW.company_id OR sc.currency<>f.currency OR sc.demo_only<>NEW.demo_only OR sc.source_hash<>NEW.source_hash OR a.group_id<>NEW.group_id OR a.company_id<>NEW.company_id OR a.status<>'ready'OR a.field_key<>'evidence_file'OR a.sha256<>NEW.sha256 OR a.byte_length<>NEW.byte_length THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='文件原字节、源工资、币种及所属不能伪造或借用';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pay_export_artifact_guard BEFORE INSERT ON ty_pay_export_artifact FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_export_artifact_guard();
CREATE TRIGGER ty_pay_export_artifact_keep BEFORE UPDATE OR DELETE ON ty_pay_export_artifact FOR EACH ROW EXECUTE FUNCTION fn_ty_pay_immutable();
